                    files={files}
                    activeFileId={activeFileId}
                    activeHeadingId={activeHeadingId}
                    expanded={expanded}
                    onToggleFile={toggleFile}
                    onSelect={handleSelect}
                    onAddFiles={() => inputRef.current?.click()}
