            >
              {!showSaved &&
                paneLayout.panes.length === 1 &&
                activeFile &&
                conversionActions(activeFile)}
              {/* Saved is a page, not an overlay: it takes the content column
                  instead of stacking on top of whatever document was open. */}
              {showSaved ? (
                savedPage
              ) : paneLayout.panes.length > 1 ? (
                /* Split view. Each pane carries its own tab strip and its own
                   document; the focused pane is what the rest of the app means
                   by "the active file", so nothing outside here has to know
                   panes exist.

                   Side by side needs width to be worth anything: two panes of a
                   320px phone are 160px each, narrower than the documents' own
                   minimum and unreadable. Splitting is only offered from the
                   docked sidebar, so a phone never opens one — but a desktop
                   window narrowed with a split already open used to land
                   exactly there. Below the width where two columns still read,
                   the panes stack instead. */
                <ResizablePanelGroup
                  orientation={splitStacks ? "vertical" : "horizontal"}
                  className="h-full"
                >
                  {paneLayout.panes.map((pane, index) => {
                    const paneFile = files.find((f) => f.id === pane.activeTabId) ?? null;
                    const paneKind = paneFile
                      ? (paneFile.kind ?? getDocumentKind(paneFile.name, paneFile.mimeType))
                      : null;
                    const paneIsBoard = paneKind === "board";
                    return (
                      <Fragment key={pane.id}>
                        {index > 0 && <ResizableHandle withHandle />}
                        <ResizablePanel
                          defaultSize={`${Math.floor(100 / paneLayout.panes.length)}%`}
                          minSize="20%"
                        >
                          <div
                            onMouseDown={() => focusPane(pane.id)}
                            className="flex h-full min-h-0 min-w-0 flex-col overflow-hidden"
                          >
                            {/* No tab strip. The open documents live in the
                                sidebar; a pane is just a column of reading, and
                                the only chrome it carries is a thin header
                                saying which document it holds and how to close
                                it. */}
                            <div
                              className={`flex h-9 shrink-0 items-center gap-2 border-b px-3 ${
                                pane.id === paneLayout.focusedPaneId
                                  ? "border-border bg-background"
                                  : "border-border/60 bg-muted/20"
                              }`}
                            >
                              <span className="min-w-0 flex-1 truncate text-xs font-medium text-muted-foreground">
                                {paneFile ? paneFile.name.replace(/\.[^.]+$/, "") : "Empty"}
                              </span>
                              <button
                                onClick={() => closePane(pane.id)}
                                aria-label="Close this pane"
                                title="Close this pane"
                                className="flex h-6 w-6 shrink-0 items-center justify-center rounded text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
                              >
                                <X className="h-3.5 w-3.5" />
                              </button>
                            </div>
                            <div
                              className={
                                paneIsBoard
                                  ? "min-h-0 min-w-0 flex-1 overflow-hidden"
                                  : "min-h-0 min-w-0 flex-1 overflow-y-auto px-4"
                              }
                            >
                              {paneFile && conversionActions(paneFile)}
                              {paneFile ? (
                                <PaneDocument
                                  file={paneFile}
                                  files={files}
                                  saved={saved}
                                  highlights={highlights}
                                  workspaceFolders={folders}
                                  onImportAttachments={importAttachments}
                                  workspaceId={workspaceId}
                                  workspaceRevision={workspaceRevision}
                                  workspaceName={workspaceNameRef.current}
                                  onContentChange={handleContentChange}
                                  onDocumentSave={handleDocumentSave}
                                  onEditorDirtyChange={(dirty) => {
                                    if (dirty) officeDirtyPanes.current.add(pane.id);
                                    else officeDirtyPanes.current.delete(pane.id);
                                  }}
                                  onRenameFile={renameFile}
                                  onAddHighlight={addHighlight}
                                  onUpdateHighlight={updateHighlight}
                                  onRemoveHighlight={removeHighlight}
                                  onRepairHighlights={repairHighlights}
                                  onToggleSaved={toggleSaved}
                                  onRemoveSaved={removeSaved}
                                  onOpenArtifact={openEmbeddedArtifact}
                                  readingMode={readingMode}
                                  contentWidth={contentWidth}
                                  // An edit request belongs to the column the
                                  // reader is working in, not to every column
                                  // showing that document. `revealInPane` has
                                  // already moved focus to the pane holding the
                                  // file, so this is that pane — and the same
                                  // document deliberately opened side by side
                                  // with itself no longer drops both copies
                                  // into the editor at once.
                                  startInEditFileId={
                                    pane.id === paneLayout.focusedPaneId ? autoEditFileId : null
                                  }
                                  mathPreferences={mathPreferences}
                                  onStartInEditConsumed={consumeStartInEdit}
                                  // Only the pane showing the document a jump
                                  // names is told about it.
                                  activeSubtopicId={
                                    paneFile.id === activeFileId ? activeHeadingId : null
                                  }
                                  highlightQuery={
                                    paneFile.id === activeFileId ? highlightQuery : null
                                  }
                                  pendingSearch={
                                    pendingSearch?.fileId === paneFile.id ? pendingSearch : null
                                  }
                                  onSearchShown={clearPendingSearch}
                                />
                              ) : (
                                <p className="px-2 py-16 text-center text-sm text-muted-foreground">
                                  Nothing open in this pane. Drag a tab here, or pick a document
                                  from the sidebar.
                                </p>
                              )}
                            </div>
                          </div>
                        </ResizablePanel>
                      </Fragment>
                    );
                  })}
                </ResizablePanelGroup>
              ) : activeFile &&
                (activeFile.kind === "markdown" ||
                  activeFile.kind === "text" ||
                  !activeFile.kind) ? (
                <MarkdownViewer
                  file={activeFile}
                  prevFile={prevFile}
                  nextFile={nextFile}
                  onNav={navFromViewer}
                  activeSubtopicId={activeHeadingId}
                  highlightQuery={highlightQuery}
                  onContentChange={handleContentChange}
                  onEditorDirtyChange={(dirty) => {
                    editorDirtyRef.current = dirty;
                  }}
                  startInEditFileId={autoEditFileId}
                  onStartInEditConsumed={consumeStartInEdit}
                  nextReadingMin={nextReadingMinutes}
                  isBookmarked={!!activePageSaved}
                  onToggleBookmark={toggleActivePageSaved}
                  highlights={activeFileHighlights}
                  onAddHighlight={addHighlightToActive}
                  onUpdateHighlight={updateHighlight}
                  onRemoveHighlight={removeHighlight}
                  onRepairHighlights={repairHighlights}
                  saved={activeFileSaved}
                  onToggleSaved={toggleSavedOnActive}
                  onRemoveSaved={removeSaved}
                  pendingSaved={pendingSaved?.fileId === activeFile.id ? pendingSaved : null}
                  onSavedShown={clearPendingSaved}
                  pendingSearch={pendingSearch?.fileId === activeFile.id ? pendingSearch : null}
                  onSearchShown={clearPendingSearch}
                  onHome={goHome}
                  onRenameFile={renameActiveFile}
                  onShareFile={shareActiveFile}
                  onAskAi={aiEnabled ? askAiFromSelection : undefined}
                  readingMode={readingMode}
                  contentWidth={contentWidth}
                  mathPreferences={mathPreferences}
                  workspaceId={workspaceId}
                  workspaceRevision={workspaceRevision}
                  workspaceFiles={files}
                  workspaceFolders={folders}
                  onImportAttachments={importAttachments}
                  workspaceName={workspaceNameRef.current}
                  onOpenArtifact={openEmbeddedArtifact}
                />
              ) : activeFile ? (
                <DocumentViewer
                  key={activeFile.id}
                  onDocumentSave={handleDocumentSave}
                  onEditorDirtyChange={(dirty) => {
                    editorDirtyRef.current = dirty;
                    if (dirty) officeDirtyPanes.current.add("main");
                    else officeDirtyPanes.current.delete("main");
                  }}
                  file={activeFile}
                  isBookmarked={!!findSaved(saved, { fileId: activeFile.id, kind: "file" })}
                  onToggleBookmark={toggleActiveDocumentSaved}
                  prevFile={prevFile}
                  nextFile={nextFile}
                  onNavFile={navToFile}
                  onContentChange={handleContentChange}
                  startInEditFileId={autoEditFileId}
                  onStartInEditConsumed={consumeStartInEdit}
                />
              ) : null}
            </main>
          </Suspense>
        </div>

        <input
          ref={inputRef}
          type="file"
          multiple
          accept={SUPPORTED_ACCEPT}
          className="hidden"
          onChange={(e) => {
            handleFileInput(e.target.files);
            e.target.value = "";
          }}
        />

        {/* Mounted only once opened. The panel is a large component whose props
          are derived from every document in the workspace; keeping it out of
          the tree until it is asked for saves that work on every render. */}
        {aiOpen && aiEnabled && (
          <Suspense fallback={null}>
            <AskAiPanel
              open
              onClose={closeAskAi}
              prefill={aiPrefill}
              initialSelection={null}
              activeFile={aiActiveFile}
              activeSection={aiActiveSection}
              files={aiFiles}
              onInsert={insertAiOutput}
              onCreateDoc={createAiDoc}
            />
          </Suspense>
        )}

        {settingsDialog}
        {moveDialog}

        {dragOverlay}
        {shareDialog}
      </div>
    </NavHistoryContext.Provider>
  );
}

import { useEffect, useRef, useState } from "react";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogTitle } from "@/components/ui/dialog";
import { loadMathlive, type MathfieldElement } from "@/lib/math-keyboard/load-mathlive";

/**
 * The math keyboard: a `<math-field>` for typing LaTeX directly, with
 * MathLive's own on-screen keyboard available underneath it for readers who
 * would rather tap symbols than remember commands.
 *
 * MathLive is loaded lazily, on the first open — see `loadMathlive`. Until it
 * resolves the field is an empty box; on a warm cache that is imperceptible,
 * and on a cold one it is still faster than waiting for the reader to notice.
 */
export function MathKeyboard({
  open,
  onOpenChange,
  initialLatex = "",
  initialDisplay = false,
  onInsert,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Seeds the field — e.g. the reader's own selection, if it looked like LaTeX. */
  initialLatex?: string;
  initialDisplay?: boolean;
  onInsert: (latex: string, display: boolean) => void;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const fieldRef = useRef<MathfieldElement | null>(null);
  const [display, setDisplay] = useState(initialDisplay);
  const [empty, setEmpty] = useState(!initialLatex.trim());

  useEffect(() => {
    if (!open) return;
    setDisplay(initialDisplay);
    setEmpty(!initialLatex.trim());
    let disposed = false;
    void loadMathlive().then(({ MathfieldElement: Ctor }) => {
      if (disposed || !containerRef.current) return;
      const mf = new Ctor();
      mf.value = initialLatex;
      // The dialog's own Insert/Cancel are the exit; the keyboard's job is
      // only ever composing the expression, shown for as long as this dialog
      // is open rather than chasing focus in and out of the field.
      mf.mathVirtualKeyboardPolicy = "manual";
      mf.smartFence = true;
      mf.addEventListener("input", () => setEmpty(!mf.value.trim()));
      containerRef.current.appendChild(mf);
      fieldRef.current = mf;
      requestAnimationFrame(() => {
        mf.focus();
        window.mathVirtualKeyboard?.show({ animate: true });
      });
    });
    return () => {
      disposed = true;
      window.mathVirtualKeyboard?.hide({ animate: false });
      fieldRef.current?.remove();
      fieldRef.current = null;
    };
    // Re-seeded only by a fresh open, not by every keystroke landing in `initialLatex`.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const commit = () => {
    const latex = fieldRef.current?.value ?? "";
    if (!latex.trim()) return;
    onInsert(latex, display);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="max-w-lg"
        onCloseAutoFocus={(event) => event.preventDefault()}
        // MathLive appends its on-screen keyboard straight to <body>, as a
        // sibling of this dialog rather than a child of it. Radix's own
        // outside-interaction dismissal has no way to know the keyboard
        // belongs to this dialog, so without this a tap on any key registers
        // as "outside" and closes the dialog mid-keystroke.
        onInteractOutside={(event) => {
          const target = event.target as Element | null;
          if (target?.closest(".ML__keyboard")) event.preventDefault();
        }}
      >
        <DialogTitle>Insert equation</DialogTitle>
        <DialogDescription>Type LaTeX, or use the math keyboard below the field.</DialogDescription>
        <div
          ref={containerRef}
          className="min-h-13 rounded-md border border-border bg-background px-3 py-2 [&_math-field]:block [&_math-field]:w-full [&_math-field]:text-lg [&_math-field]:outline-none"
        />
        <label className="flex items-center gap-2 text-sm text-muted-foreground">
          <input
            type="checkbox"
            checked={display}
            onChange={(e) => setDisplay(e.target.checked)}
            className="h-3.5 w-3.5 accent-primary"
          />
          Display equation, on its own centred line
        </label>
        <DialogFooter>
          <button
            type="button"
            onClick={() => onOpenChange(false)}
            className="inline-flex items-center gap-1.5 rounded-md border border-border bg-muted px-3 py-1.5 text-sm font-medium text-foreground transition-opacity hover:bg-muted/80 active:scale-95"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={commit}
            disabled={empty}
            className="inline-flex items-center gap-1.5 rounded-md bg-foreground px-3 py-1.5 text-sm font-medium text-background transition-opacity hover:opacity-90 active:scale-95 disabled:opacity-40"
          >
            Insert
          </button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { Home, Star, Plus, Settings, FolderOpen, Trash2, CheckCircle2 } from "lucide-react";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger } from "@/components/ui/sheet";
import { useState, useRef, useEffect } from "react";

// Assuming we pass in what we need
export function BottomNav({
  workspaces,
  currentWorkspaceId,
  onNewWorkspace,
  bookmarks,
  onSelectBookmark,
  onRemoveBookmark,
  onHome,
  onUpload,
  onSettings,
}: any) {
  const currentWorkspace = workspaces.find((w: any) => w.id === currentWorkspaceId);

  // Workspace Creation State
  const [isCreating, setIsCreating] = useState(false);
  const [newName, setNewName] = useState("");
  const [wsSheetOpen, setWsSheetOpen] = useState(false);

  const handleCreate = () => {
    if (newName.trim()) {
      onNewWorkspace(newName.trim());
      setIsCreating(false);
      setNewName("");
      // Don't auto-close the sheet immediately so they see it appear, or close it:
      setWsSheetOpen(false);
    }
  };

  return (
    <nav className="app-surface fixed bottom-0 left-0 right-0 z-(--z-nav) flex h-16 items-center justify-between border-t border-border px-6 lg:hidden">
      {/* 1. Home */}
      <button
        onClick={onHome}
        className="flex flex-col items-center justify-center gap-1 text-muted-foreground transition-colors hover:text-foreground"
      >
        <Home className="h-5 w-5" />
        <span className="text-xs font-medium">Home</span>
      </button>

      {/* 2. Bookmarks (Bottom Sheet) */}
      <Sheet>
