            <Star className="h-5 w-5" />
            <span className="text-xs font-medium">Bookmarks</span>
          </button>
        </SheetTrigger>
        <SheetContent side="bottom" className="max-h-[80vh] overflow-y-auto">
          <SheetHeader>
            <SheetTitle>Bookmarks</SheetTitle>
