                    {bm.name}
                  </button>
                  <button
                    onClick={() => onRemoveBookmark(bm.fileId, bm.subtopicId)}
                    className="text-muted-foreground hover:text-destructive opacity-0 group-hover:opacity-100 transition-opacity p-2"
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              ))
            )}
          </div>
        </SheetContent>
      </Sheet>

      {/* 3. Upload CTA */}
      <button
        onClick={onUpload}
        className="flex h-12 w-12 -translate-y-4 items-center justify-center rounded-full bg-primary text-primary-foreground shadow-lg transition-transform hover:scale-105 active:scale-95"
      >
        <Plus className="h-6 w-6" />
      </button>

      {/* 4. Settings */}
      <button
        onClick={onSettings}
        className="flex flex-col items-center justify-center gap-1 text-muted-foreground transition-colors hover:text-foreground"
      >
        <Settings className="h-5 w-5" />
        <span className="text-xs font-medium">Settings</span>
      </button>

      {/* 5. Workspace (Bottom Sheet) */}
      <Sheet open={wsSheetOpen} onOpenChange={setWsSheetOpen}>
        <SheetTrigger asChild>
          <button className="flex flex-col items-center justify-center gap-1 text-muted-foreground transition-colors hover:text-foreground">
            <FolderOpen className="h-5 w-5" />
            <span className="text-xs font-medium">Workspace</span>
          </button>
        </SheetTrigger>
        <SheetContent side="bottom" className="max-h-[80vh] overflow-y-auto">
          <SheetHeader>
            <SheetTitle>Workspaces</SheetTitle>
          </SheetHeader>
          <div className="mt-4 flex flex-col gap-2">
            {/* The workspace you are in, then one row into workspace settings
                for the rest. Listing them all here grew the sheet without
                bound on the smallest screens. */}
            {currentWorkspace && (
              <div className="flex items-center justify-between rounded-lg bg-accent p-3 text-sm font-medium text-foreground">
                {currentWorkspace.name}
                <CheckCircle2 className="h-4 w-4 text-primary" />
              </div>
            )}
            <button
              onClick={() => {
                setWsSheetOpen(false);
                onSettings("workspace");
              }}
              className="flex items-center gap-2 rounded-lg p-3 text-left text-sm font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
            >
              <FolderOpen className="h-4 w-4 shrink-0" />
              All workspaces
            </button>

            {/* Create inline input */}
            <div className="mt-2">
              {isCreating ? (
                <div className="flex items-center gap-2 rounded-lg border border-border bg-background p-2">
                  <input
                    type="text"
                    autoFocus
                    placeholder="Workspace name..."
                    value={newName}
                    onChange={(e) => setNewName(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") handleCreate();
                      if (e.key === "Escape") {
                        setIsCreating(false);
                        setNewName("");
                      }
                    }}
                    className="flex-1 bg-transparent px-2 text-sm font-medium outline-none placeholder:font-normal"
                  />
                  <button
                    onClick={handleCreate}
                    disabled={!newName.trim()}
                    className="text-primary hover:text-primary/80 disabled:opacity-50"
                  >
                    <CheckCircle2 className="h-5 w-5" />
                  </button>
                </div>
              ) : (
                <button
                  onClick={() => setIsCreating(true)}
                  className="flex w-full items-center gap-2 rounded-lg border border-dashed border-border p-3 text-sm font-medium text-muted-foreground transition-colors hover:border-primary/50 hover:text-foreground"
                >
                  <Plus className="h-4 w-4" />
                  New Workspace
                </button>
              )}
            </div>
          </div>
        </SheetContent>
      </Sheet>
    </nav>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";
import { X } from "lucide-react";
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from "@/components/ui/resizable";
import { useMediaQuery } from "@/hooks/use-media-query";

export type InteractiveKind = "html" | "react";
export type InteractiveMode = "standard" | "preview" | "split" | "playground";

interface InteractiveBlockProps {
  kind: InteractiveKind;
  code: string;
  meta?: string;
}

interface RuntimeError {
  message: string;
  stack?: string;
}

const FRAME_MESSAGE = "docucraft:interactive";
const MIN_FRAME_HEIGHT = 176;
const MAX_FRAME_HEIGHT = 960;

export function interactiveMode(meta?: string): InteractiveMode {
  const flags = new Set((meta ?? "").toLowerCase().split(/\s+/).filter(Boolean));
  if (flags.has("playground")) return "playground";
  if (flags.has("split")) return "split";
  if (flags.has("preview")) return "preview";
  return "standard";
}

export function InteractiveBlock({ kind, code, meta }: InteractiveBlockProps) {
  const mode = interactiveMode(meta);
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const sectionRef = useRef<HTMLElement>(null);
  const runId = useRef(0);
  const [source, setSource] = useState(code);
  const [visible, setVisible] = useState(false);
  const [frameReady, setFrameReady] = useState(false);
  const [frameHeight, setFrameHeight] = useState(300);
  const [error, setError] = useState<RuntimeError | null>(null);
  const [theme, setTheme] = useState<"light" | "dark">("light");
  const [compiled, setCompiled] = useState<string | RuntimeError | null>(null);

  useEffect(() => setSource(code), [code]);

  // Avoid compiling/mounting below-the-fold examples until they approach the
  // reader. The frame stays empty until then, so each document can hold many demos.
  useEffect(() => {
    if (!sectionRef.current) return;
    const observer = new IntersectionObserver(
      ([entry]) => entry.isIntersecting && setVisible(true),
      { rootMargin: "320px 0px" },
    );
    observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const syncTheme = () =>
      setTheme(document.documentElement.classList.contains("dark") ? "dark" : "light");
    syncTheme();
    const observer = new MutationObserver(syncTheme);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });
    return () => observer.disconnect();
  }, []);

  // Babel is a sizeable browser compiler. Load and run it only for React
  // examples that have reached the viewport (or entered playground mode).
  useEffect(() => {
    if (kind !== "react" || !visible) return;
    let cancelled = false;
    setCompiled(null);
    void import("@babel/standalone").then(({ transform }) => {
      try {
        if (/^\s*import\s/m.test(source)) {
          throw new Error("React and hooks are provided automatically; remove import statements.");
        }
        const output = transform(source, {
          filename: "interactive-component.tsx",
          presets: ["typescript", ["react", { runtime: "classic" }]],
          plugins: ["transform-modules-commonjs"],
        }).code;
        if (!cancelled) setCompiled(output);
      } catch (cause) {
        if (!cancelled) setCompiled(toRuntimeError(cause));
      }
    });
    return () => {
      cancelled = true;
    };
  }, [kind, source, visible]);

  const sendToFrame = useCallback(() => {
    const frame = iframeRef.current?.contentWindow;
    if (!frame || !visible || !frameReady) return;
    if (compiled === null) return;
    if (typeof compiled !== "string") {
      setError(compiled);
      return;
    }
    setError(null);
    const id = `${++runId.current}`;
    if (kind === "react") {
      frame.postMessage({ type: "docucraft:interactive-run", id, code: compiled, theme }, "*");
    }
  }, [compiled, frameReady, kind, theme, visible]);

  useEffect(() => {
    if (kind === "react") sendToFrame();
  }, [sendToFrame]);

  useEffect(() => {
    const onMessage = (event: MessageEvent) => {
      if (event.source !== iframeRef.current?.contentWindow || event.data?.type !== FRAME_MESSAGE)
        return;
      const data = event.data as {
        event?: string;
        height?: number;
        message?: string;
        stack?: string;
      };
      if (data.event === "booted") setFrameReady(true);
      if (data.event === "height" && typeof data.height === "number") {
        setFrameHeight(Math.min(MAX_FRAME_HEIGHT, Math.max(MIN_FRAME_HEIGHT, data.height + 2)));
      }
      if (data.event === "error")
        setError({ message: data.message ?? "The preview failed.", stack: data.stack });
    };
    window.addEventListener("message", onMessage);
    return () => window.removeEventListener("message", onMessage);
  }, []);

  const playground = mode === "playground";
  const sourcePanel = playground ? (
    <textarea
      aria-label="Interactive component source"
      value={source}
      onChange={(event) => setSource(event.target.value)}
      spellCheck={false}
      className="interactive-editor"
    />
  ) : (
    <pre className="interactive-source">
      <code>{source}</code>
    </pre>
  );

  const preview = visible ? (
    <div className="interactive-preview">
      <iframe
        ref={iframeRef}
        title={`Interactive ${kind} preview`}
        sandbox="allow-scripts"
        referrerPolicy="no-referrer"
        src={kind === "react" ? "/interactive-runtime" : undefined}
        srcDoc={kind === "html" ? htmlDocument(source, theme) : undefined}
        onLoad={() => {
          if (kind === "html") setFrameReady(true);
        }}
        style={{ height: frameHeight }}
      />
      {error && <ErrorPanel error={error} onDismiss={() => setError(null)} />}
    </div>
  ) : (
    <div className="interactive-loading">Preparing live example…</div>
  );

  const showSource = mode === "split" || playground;
  const split = mode === "split" || playground;
  /* Matches the 640px the rest of this block's narrow-screen styling uses. */
  const stackSplit = useMediaQuery("(max-width: 640px)");

  return (
    <section ref={sectionRef} className="interactive-block not-prose">
      {showSource && split ? (
        /* Code beside preview needs two readable columns. On a phone the block
           is ~290px wide, so each half would be ~145px — narrower than a line
           of the code it is showing. The stylesheet used to try to stack these
           through `[data-panel-group-direction="horizontal"]`, an attribute
           this version of the library does not emit, so the rule never applied
           and the two panes stayed side by side however narrow the screen got.
           Driving the group's own orientation is what actually turns it. */
        <ResizablePanelGroup
          orientation={stackSplit ? "vertical" : "horizontal"}
          className="interactive-split"
        >
          <ResizablePanel defaultSize="50%" minSize="25%">
            {sourcePanel}
          </ResizablePanel>
          <ResizableHandle withHandle />
          <ResizablePanel defaultSize="50%" minSize="25%">
            {preview}
          </ResizablePanel>
        </ResizablePanelGroup>
      ) : (
        preview
      )}
    </section>
  );
}

function ErrorPanel({ error, onDismiss }: { error: RuntimeError; onDismiss: () => void }) {
  return (
    <div className="interactive-error" role="alert">
      <div>
        <strong>Preview error</strong>
        <button onClick={onDismiss} aria-label="Dismiss error">
          <X size={14} />
        </button>
      </div>
      <p>{error.message}</p>
      {error.stack && <pre>{error.stack}</pre>}
    </div>
  );
}

function toRuntimeError(value: unknown): RuntimeError {
  const error = value instanceof Error ? value : new Error(String(value));
  return { message: error.message, stack: error.stack };
}

function htmlDocument(source: string, theme: "light" | "dark") {
  const colors =
    theme === "dark"
      ? "color-scheme:dark;background:#151b2b;color:#edf2ff"
      : "color-scheme:light;background:#fff;color:#172033";
  return `<!doctype html><html><head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data: blob:; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'none'; font-src data:; media-src data: blob:" />
    <style>html,body{min-height:100%;margin:0}body{padding:18px;font:15px/1.5 ui-sans-serif,system-ui,sans-serif;${colors}}*{box-sizing:border-box}</style>
    <script>
      (() => {
        const deny=()=>{throw new Error('This API is disabled inside interactive documentation blocks.')};
        const UnsafeFunction=Function;
        window.open=deny; window.fetch=deny; window.eval=deny; window.Function=deny;
        ['localStorage','sessionStorage','indexedDB','caches','Notification','Clipboard','showOpenFilePicker','showSaveFilePicker'].forEach((name)=>{try{Object.defineProperty(window,name,{configurable:true,get:deny,set:deny})}catch{}});
        try{Object.defineProperty(document,'cookie',{configurable:true,get:deny,set:deny})}catch{}
        if(navigator.mediaDevices) navigator.mediaDevices.getUserMedia=deny;
        if(navigator.geolocation) navigator.geolocation.getCurrentPosition=deny;
        new ResizeObserver(()=>parent.postMessage({type:'${FRAME_MESSAGE}',event:'height',height:document.documentElement.scrollHeight},'*')).observe(document.documentElement);
        addEventListener('error',(event)=>parent.postMessage({type:'${FRAME_MESSAGE}',event:'error',message:event.message,stack:event.error&&event.error.stack},'*'));
        parent.postMessage({type:'${FRAME_MESSAGE}',event:'booted'},'*');
        void UnsafeFunction;
      })();
    </script>
  </head><body>${source}</body></html>`;
}

import { memo, useMemo, useState } from "react";
import { ChevronRight } from "lucide-react";

/** A container node's path, joined with "/" — the identity used by the open set. */
type Path = string;

/** How deep the tree is expanded when a document first opens. */
const DEFAULT_OPEN_DEPTH = 1;

/**
 * Guard against pathological documents: a file with tens of thousands of nodes
 * would mount that many rows at once. Everything past the cap stays collapsed
 * under its parent, which the reader can still open branch by branch.
 */
const MAX_ROWS = 4000;

function isContainer(value: unknown): value is Record<string, unknown> | unknown[] {
  return value !== null && typeof value === "object";
}

function entriesOf(value: Record<string, unknown> | unknown[]): [string, unknown][] {
  return Array.isArray(value)
    ? value.map((item, index) => [String(index), item] as [string, unknown])
    : Object.entries(value);
}

/** `{3}` / `[12]` — the summary shown on a collapsed branch. */
function summarize(value: Record<string, unknown> | unknown[]): string {
  const count = Array.isArray(value) ? value.length : Object.keys(value).length;
  return Array.isArray(value) ? `[${count}]` : `{${count}}`;
}

/**
 * Every container path in the document, so "Expand all" doesn't have to walk the
 * tree again and the initial open set can be built by depth.
 */
function collectPaths(value: unknown, path: Path, depth: number, out: Map<Path, number>) {
  if (!isContainer(value)) return;
  out.set(path, depth);
  for (const [key, child] of entriesOf(value)) {
    collectPaths(child, `${path}/${key}`, depth + 1, out);
  }
}

function ValueText({ value }: { value: unknown }) {
  if (typeof value === "string")
    return <span style={{ color: "var(--code-string)" }}>&quot;{value}&quot;</span>;
  if (typeof value === "number") return <span style={{ color: "var(--code-number)" }}>{String(value)}</span>;
  if (typeof value === "boolean") return <span className="text-purple-300">{String(value)}</span>;
  if (value === null) return <span style={{ color: "var(--code-punct)" }}>null</span>;
  return <span className="text-foreground">{String(value)}</span>;
}

function Row({
  label,
  value,
  path,
  depth,
  open,
  onToggle,
  query,
  budget,
}: {
  label: string | null;
  value: unknown;
  path: Path;
  depth: number;
  open: Set<Path>;
  onToggle: (path: Path) => void;
  query: string;
  /** Shared, mutable row allowance — see MAX_ROWS. */
  budget: { left: number };
}) {
  const container = isContainer(value);
  const expanded = container && open.has(path);
  const text = `${label ?? ""} ${container ? "" : String(value)}`.toLowerCase();
  const hit = query.length > 0 && text.includes(query);

  const children = expanded ? entriesOf(value as Record<string, unknown>) : [];
  budget.left -= children.length;
  const truncated = budget.left < 0;

  return (
    <div>
      <div
        className={`flex items-start rounded ${hit ? "bg-primary/15" : ""}`}
        style={{ paddingLeft: depth * 14 }}
      >
        {container ? (
          <button
            type="button"
            onClick={() => onToggle(path)}
            aria-expanded={expanded}
            aria-label={expanded ? `Collapse ${label ?? "root"}` : `Expand ${label ?? "root"}`}
            className="mt-0.5 flex h-4 w-4 shrink-0 items-center justify-center rounded text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
          >
            <ChevronRight
              className={`h-3 w-3 transition-transform ${expanded ? "rotate-90" : ""}`}
            />
          </button>
        ) : (
          <span className="h-4 w-4 shrink-0" />
        )}
        <div className="min-w-0 flex-1 break-words pl-1">
          {label !== null && <span style={{ color: "var(--code-key)" }}>{label}</span>}
          {label !== null && <span style={{ color: "var(--code-punct)" }}>: </span>}
          {container ? (
            <span
              className="cursor-pointer" style={{ color: "var(--code-punct)" }}
              onClick={() => onToggle(path)}
              role="presentation"
            >
              {summarize(value as Record<string, unknown>)}
            </span>
          ) : (
            <ValueText value={value} />
          )}
        </div>
      </div>
      {expanded && !truncated
        ? children.map(([key, child]) => (
            <Row
              key={key}
              label={key}
              value={child}
              path={`${path}/${key}`}
              depth={depth + 1}
              open={open}
              onToggle={onToggle}
              query={query}
              budget={budget}
            />
          ))
        : null}
      {expanded && truncated ? (
        <div className="py-1 text-xs text-muted-foreground" style={{ paddingLeft: (depth + 1) * 14 }}>
          Too many nodes to draw here — collapse another branch to see these.
        </div>
      ) : null}
    </div>
  );
}

/**
 * Collapsible tree over parsed JSON. The parsed value is owned by the caller so
 * that switching between this and the raw editor doesn't re-parse the document.
 */
function JsonTreeImpl({ value, query = "" }: { value: unknown; query?: string }) {
  const paths = useMemo(() => {
    const map = new Map<Path, number>();
    collectPaths(value, "", 0, map);
    return map;
  }, [value]);

  const [open, setOpen] = useState<Set<Path>>(() => {
    const initial = new Set<Path>();
    for (const [path, depth] of paths) if (depth <= DEFAULT_OPEN_DEPTH) initial.add(path);
    return initial;
  });

  const toggle = (path: Path) =>
    setOpen((previous) => {
      const next = new Set(previous);
      if (next.has(path)) next.delete(path);
      else next.add(path);
      return next;
    });

  const allOpen = open.size === paths.size;

  return (
    <div className="overflow-hidden rounded-xl border border-hairline bg-surface-sunken shadow-(--shadow-1)">
      {/* Inside the panel rather than floating above it: these act on the tree
          below, and as a separate row they read as page-level chrome. */}
      <div className="flex items-center justify-end gap-1 border-b border-hairline px-2 py-1.5">
        <button
          type="button"
          onClick={() => setOpen(new Set(paths.keys()))}
          disabled={allOpen}
          className="rounded px-2 py-1 text-2xs font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:opacity-30 disabled:hover:bg-transparent"
        >
          Expand all
        </button>
        <button
          type="button"
          onClick={() => setOpen(new Set())}
          disabled={open.size === 0}
          className="rounded px-2 py-1 text-2xs font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:opacity-30 disabled:hover:bg-transparent"
        >
          Collapse all
        </button>
      </div>
      <div className="overflow-x-auto p-4 font-mono text-sm leading-6 text-foreground">
        <Row
          label={null}
          value={value}
          path=""
          depth={0}
          open={open}
          onToggle={toggle}
          query={query.toLowerCase()}
          budget={{ left: MAX_ROWS }}
        />
      </div>
    </div>
  );
}

export const JsonTree = memo(JsonTreeImpl);

