                        if (menu.mode === "create") {
                          onAddHighlight({
                            text: menu.text,
                            color,
                            label: menu.label.trim() || undefined,
                            subtopicId: singleMode ? undefined : activeChunk.id,
                            start: menu.start,
                            end: menu.end,
                            prefix: menu.prefix,
                            suffix: menu.suffix,
                          });
                          window.getSelection()?.removeAllRanges();
                        } else {
                          onUpdateHighlight(menu.hl.id, { color });
                        }
                        setMenu(null);
                      }}
                    />
