          )}

        {lightbox && <Lightbox {...lightbox} onClose={() => setLightbox(null)} />}

        <div
          className="docs-reading-pane mx-auto flex w-full gap-8 px-6 py-10 md:px-10 md:py-16"
          // A share of the pane's own inline size (`cqi`, from the
          // `container-type: inline-size` below), not of the viewport — so the
          // column already tracks the sidebar being collapsed or expanded, and
          // only the slider in Settings needs to move it. styles.css only reads
          // this at `md:` and up: a phone-width column cut down to 40-50% of an
          // already-narrow screen would be unreadable.
          style={{ "--docs-content-width": `${contentWidth}cqi` } as CSSProperties}
        >
          <article
            onMouseUp={() => openCreateMenu()}
            onContextMenu={onContextMenu}
            className="docs-prose mx-auto min-w-0 flex-1"
          >
            {/*
             * The masthead.
             *
             * A section used to open with its title and a reading time and
             * nothing else, which left two questions unanswered on every
             * screen: which document is this, and how far through it am I. The
             * file name was only ever visible in the sidebar, so with the
             * sidebar collapsed — or on a phone, where it is a drawer — the
             * open document had no name at all.
             *
             * Three lines, in the order they are wanted: what this is, what
             * it is called, and what it will cost to read.
             */}
            {!singleMode && (
              <header className="mb-10">
                <p className="mb-3 flex min-w-0 items-center gap-2 text-xs font-medium text-muted-foreground">
                  <FileText className="h-3.5 w-3.5 shrink-0" />
                  <span className="truncate">{file.name}</span>
                  {allChunks.length > 1 && (
                    <>
                      <span aria-hidden className="text-border">
                        /
                      </span>
                      <span className="shrink-0 tabular-nums">
                        {chunkIndex + 1} of {allChunks.length}
                      </span>
                    </>
                  )}
                </p>
                <h1 className="wrap-break-word text-pretty text-[2rem] font-[680] leading-[1.12] tracking-[-0.028em] text-foreground sm:text-[2.6rem]">
                  {activeChunk.title}
                </h1>
                <p className="mt-3.5 flex items-center gap-2 text-xs font-medium text-muted-foreground">
                  <span className="inline-flex items-center gap-1.5">
                    <Clock className="h-3.5 w-3.5" />≈ {stats.readingMin} min read
                  </span>
                  <span aria-hidden className="text-border">
                    ·
                  </span>
                  <span className="tabular-nums">{stats.words.toLocaleString()} words</span>
                </p>
              </header>
            )}

            {editMode ? (
              <MarkdownEditor
                // Keyed by document: switching files tears the editor down and
                // builds a new one, rather than handing the previous document's
                // draft to the next document's instance.
                key={file.id}
                ref={editorRef}
                fileId={file.id}
                initialContent={file.content}
                onSave={saveDraft}
                onDone={leaveEditMode}
                onCancel={cancelEdit}
                onDirtyChange={setEditorDirty}
                inspectMissed={inspectMissed}
                fileName={file.name}
                onRename={onRenameFile}
                mediaContext={{
                  workspaceId,
                  workspaceRevision,
                  workspaceFiles,
                  workspaceFolders,
                  workspaceName,
                  sourceFile: file,
                }}
                onImportAttachments={onImportAttachments}
              />
            ) : (
              <div
                key={singleMode ? "full" : activeChunk.id}
                ref={contentRef}
                onClick={onContentClick}
              >
                <SavedContext.Provider value={savedCtx}>
                  <CollapseContext.Provider value={collapseCtx}>
                    <MarkdownContent
                      urlTransform={mediaUrlTransform}
                      remarkPlugins={remarkPlugins}
                      rehypePlugins={rehypePlugins}
                      components={components}
                    >
                      {markdownSource}
                    </MarkdownContent>
                  </CollapseContext.Provider>
                </SavedContext.Provider>
              </div>
            )}

            {/* One pager for both reading modes. Paged mode steps section by
                section and falls through to the next file at the end of a
                document; single page shows everything, so it steps files. */}
            {!editMode && (
              <ViewerPager
                className="mt-16 border-t border-border"
                nextEyebrow={
                  nextChunk ? `Next ${chunkIndex + 2}/${allChunks.length}` : "Next chapter"
                }
                nav={{
                  onPrev: () => {
                    if (!singleMode && prevChunk) onNav(file.id, prevChunk.id);
                  },
                  onNext: () => {
                    if (!singleMode && nextChunk) onNav(file.id, nextChunk.id);
                  },
                  prevDisabled: singleMode || !prevChunk,
                  nextDisabled: singleMode || !nextChunk,
                  prevLabel: !singleMode && prevChunk ? `Previous: ${prevChunk.title}` : "Previous",
                  nextLabel: !singleMode && nextChunk ? nextChunk.title || "Next" : "Next",
                }}
              />
            )}
          </article>
        </div>

        <ReadingProgress
          containerRef={containerRef}
          contentRef={contentRef}
          revision={markdownSource}
          hidden={editMode}
        />
      </div>
    </div>
  );
}

/**
 * Rendering a document means parsing markdown, painting highlights and walking
 * the resulting tree, so this component must not re-render just because the app
 * shell around it did. Every prop it takes is either a primitive or held to a
 * stable identity in `DocsApp`, which is what makes the memo effective.
 */
export const MarkdownViewer = memo(MarkdownViewerImpl);

import type { DocumentUpdate } from "@/services/office-editing";
import type { MdFile } from "@/lib/markdown/markdown-utils";
import { ViewerHeader, type ViewerNav } from "../../navigation/ViewerHeader";

export interface Props {
  file: MdFile;
  isBookmarked?: boolean;
  onToggleBookmark?: () => void;
  onRemoveFile?: () => void;
  /** Sibling files, so the shared header's prev/next can move between files. */
  prevFile?: MdFile | null;
  nextFile?: MdFile | null;
  onNavFile?: (fileId: string) => void;
  /** Rendered inside markdown content: strip all chrome, show only the content. */
  embedded?: boolean;
  /** Fill a bounded parent (such as a split pane) instead of the viewport. */
  fillAvailableHeight?: boolean;
  /** Persist an edited document. Omitted where the viewer is read-only. */
  onContentChange?: (fileId: string, content: string) => void;
  onDocumentSave?: (fileId: string, update: DocumentUpdate) => void;
  onEditorDirtyChange?: (dirty: boolean) => void;
  /** Opens the workspace command palette from the header's search field. */
  onOpenPalette?: () => void;
  /**
   * Document the sidebar asked to edit. Editing is entered from the file's
   * three-dots menu rather than a header button, so the request arrives here
   * the same way it does for markdown. Cleared through `onStartInEditConsumed`.
   */
  startInEditFileId?: string | null;
  onStartInEditConsumed?: () => void;
}
export interface GoogleProps extends Props {
  isSlides: boolean;
}

/**
 * Document name without its extension, for labels. Unlike the markdown
 * viewer's version this drops any trailing extension, since this file serves
 * every document type.
 */
export const stripExt = (name: string) => name.replace(/\.[^./\\]+$/, "");

/** File-level prev/next for the shared header — used by every non-deck viewer. */
export function useFileNav({
  prevFile,
  nextFile,
  onNavFile,
}: Pick<Props, "prevFile" | "nextFile" | "onNavFile">): ViewerNav {
  return {
    onPrev: () => prevFile && onNavFile?.(prevFile.id),
    onNext: () => nextFile && onNavFile?.(nextFile.id),
    prevDisabled: !prevFile || !onNavFile,
    nextDisabled: !nextFile || !onNavFile,
    // The pager names the destination rather than the direction — the arrow
    // already says which way it goes.
    prevLabel: prevFile ? `Previous: ${stripExt(prevFile.name)}` : "Previous file",
    nextLabel: nextFile ? stripExt(nextFile.name) : "Next file",
  };
}

/**
 * The masthead a non-text file opens with.
 *
 * Markdown documents get their title, file name and reading time from the
 * reader's own header. Everything else — a sheet, a JSON file, a deck — opened
 * straight into its content with no name anywhere on screen, on the reasoning
 * that the sidebar already marks the active file. It does, until the sidebar is
 * collapsed, or the window is narrow enough that it becomes a drawer, or the
 * reader simply came back to the tab: then the open document is anonymous.
 *
 * Costs one line, and gives every file type the same opening as a document.
 */
export function ViewerMasthead({
  file,
  kindLabel,
  meta,
  actions,
}: {
  file: MdFile;
  kindLabel: string;
  /** One short fact about the file, e.g. "9 rows · 5 columns". */
  meta?: React.ReactNode;
  actions?: React.ReactNode;
}) {
  return (
    <header className="mb-4 flex items-end justify-between gap-4">
      <div className="min-w-0">
        <p className="flex items-center gap-2 text-2xs font-semibold uppercase tracking-wider text-muted-foreground">
          <span>{kindLabel}</span>
          {meta && (
            <>
              <span aria-hidden className="font-normal text-border">
                ·
              </span>
              <span className="font-medium normal-case tracking-normal">{meta}</span>
            </>
          )}
        </p>
        <h1 className="mt-1 truncate text-lg font-semibold tracking-[-0.015em] text-foreground">
          {file.name}
        </h1>
      </div>
      {actions && <div className="flex shrink-0 items-center gap-1.5">{actions}</div>}
    </header>
  );
}

export function ViewerFrame({
  children,
  action,
  navAction,
  isBookmarked,
  onToggleBookmark,
  prevFile,
  nextFile,
  onNavFile,
  onOpenPalette,
}: {
  /**
   * Accepted so call sites can keep passing the open document, and to leave the
   * per-type `icon` prop in place, but the header no longer renders either: the
   * sidebar marks the active file, so this space belongs to search.
   */
  file?: MdFile;
  children: React.ReactNode;
  action?: React.ReactNode;
  navAction?: React.ReactNode;
  icon?: React.ReactNode;
  isBookmarked?: boolean;
  onToggleBookmark?: () => void;
} & Pick<Props, "prevFile" | "nextFile" | "onNavFile" | "onOpenPalette">) {
  const nav = useFileNav({ prevFile, nextFile, onNavFile });
  return (
    <section className="min-h-[calc(100dvh-4rem)] bg-background">
      <ViewerHeader
        navAction={navAction}
        // Starring and editing live in the file's three-dots menu in the
        // sidebar, next to the other things you do *to* a document. What stays
        // here is per-view state — zoom, fullscreen, the mind map — which has
        // no meaning anywhere else.
        actions={action}
      />
      {children}
    </section>
  );
}

