export type SaveStatus = "idle" | "saving" | "saved" | "restored";

export class WorkspaceConflictError extends Error {
  constructor() {
    super(
      "This workspace changed in another tab. Export any unsaved edits, then reload before continuing.",
    );
    this.name = "WorkspaceConflictError";
  }
}

const DB_NAME = "localdox";
const DB_VERSION = 2;
const STORE = "workspaces";
const FILES = "files";
const SUMMARIES = "workspace-summaries";

export interface WorkspaceSummary {
  id: string;
  name: string;
  createdAt: number;
  updatedAt: number;
  docCount: number;
}

type StoredWorkspace = Omit<WorkspaceRecord, "files"> & { fileIds: string[]; revision: string };
type StoredFile = PersistedFile & { workspaceId: string };

function summaryOf(w: WorkspaceRecord): WorkspaceSummary {
  return {
    id: w.id,
    name: w.name,
    createdAt: w.createdAt,
    updatedAt: w.updatedAt,
    docCount: w.files.length,
  };
}

// Retain only the last workspace's file references, never a second copy of its
// document bytes. The on-disk revision guards this optimization across tabs.
let lastWrite: { id: string; revision: string; files: Map<string, PersistedFile> } | null = null;
const knownRevisions = new Map<string, string>();

function sameFile(a: PersistedFile | undefined, b: PersistedFile): boolean {
  return (
    !!a &&
    a.id === b.id &&
    a.name === b.name &&
    a.content === b.content &&
    a.data === b.data &&
    a.mimeType === b.mimeType &&
    a.size === b.size &&
    a.addedAt === b.addedAt &&
    a.kind === b.kind &&
    a.folderId === b.folderId &&
    a.deletedAt === b.deletedAt &&
    JSON.stringify(a.derivedFrom) === JSON.stringify(b.derivedFrom)
  );
}

let dbPromise: Promise<IDBDatabase> | null = null;

function openDb(): Promise<IDBDatabase> {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise<IDBDatabase>((resolve, reject) => {
    let blocked = false;
    if (typeof indexedDB === "undefined") {
      reject(new Error("IndexedDB unavailable"));
      return;
    }
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = () => {
      if (blocked) {
        req.transaction!.abort();
        return;
      }
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE)) {
        db.createObjectStore(STORE, { keyPath: "id" });
      }
      const files = db.createObjectStore(FILES, { keyPath: ["workspaceId", "id"] });
      files.createIndex("workspaceId", "workspaceId");
      const summaries = db.createObjectStore(SUMMARIES, { keyPath: "id" });
      // One atomic migration: an aborted upgrade leaves the v1 data intact.
      // Use a cursor so only one legacy workspace is materialized at a time.
      const cursor = req.transaction!.objectStore(STORE).openCursor();
      cursor.onsuccess = () => {
        const row = cursor.result;
        if (!row) return;
        const workspace = row.value as WorkspaceRecord;
        for (const file of workspace.files) files.put({ ...file, workspaceId: workspace.id });
        const { files: documents, ...metadata } = workspace;
        row.update({
          ...metadata,
          fileIds: documents.map((f) => f.id),
          revision: crypto.randomUUID(),
        });
        summaries.put(summaryOf(workspace));
        row.continue();
      };
    };
    req.onsuccess = () => {
      const db = req.result;
      if (blocked) {
        db.close();
        return;
      }
      db.onversionchange = () => {
        db.close();
        dbPromise = null;
        lastWrite = null;
      };
      db.onclose = () => {
        dbPromise = null;
        lastWrite = null;
      };
      resolve(db);
    };
    req.onerror = () => reject(req.error);
    req.onblocked = () => {
      blocked = true;
      reject(new Error("Close other Localdox tabs to finish updating local storage"));
    };
  }).catch((error) => {
    dbPromise = null;
    throw error;
  });
  return dbPromise;
}

function request<T>(
  mode: IDBTransactionMode,
  fn: (store: IDBObjectStore) => IDBRequest<T>,
  store = STORE,
): Promise<T> {
  return openDb().then(
    (db) =>
      new Promise<T>((resolve, reject) => {
        const t = db.transaction(store, mode);
        const req = fn(t.objectStore(store));
        t.oncomplete = () => resolve(req.result);
        t.onabort = () => reject(t.error ?? new Error("Local storage transaction aborted"));
        req.onerror = () => reject(req.error);
      }),
  );
}

async function deleteDatabase(): Promise<void> {
  knownRevisions.clear();
  const openDatabase = dbPromise;
  dbPromise = null;
  lastWrite = null;

  try {
    (await openDatabase)?.close();
  } catch {
    // The database may never have opened; deletion can still proceed.
  }

  if (typeof indexedDB === "undefined") return;

  await new Promise<void>((resolve, reject) => {
    const req = indexedDB.deleteDatabase(DB_NAME);
    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error ?? new Error("Could not delete local database"));
    req.onblocked = () => reject(new Error("Close Localdox in other tabs before clearing storage"));
  });
}

export const persistence = {
  async getWorkspace(id: string): Promise<WorkspaceRecord | undefined> {
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction([STORE, FILES], "readonly");
      const metadata = tx.objectStore(STORE).get(id);
      const documents = tx.objectStore(FILES).index("workspaceId").getAll(id);
      tx.onabort = () => reject(tx.error ?? new Error("Could not read workspace"));
      tx.oncomplete = () => {
        const record = metadata.result as StoredWorkspace | undefined;
        if (!record) {
          resolve(undefined);
          return;
        }
        const { fileIds, revision, ...workspace } = record;
        const byId = new Map<string, PersistedFile>(
          (documents.result as StoredFile[]).map(({ workspaceId: _id, ...file }) => [
            file.id,
            file,
          ]),
        );
        const files = fileIds.map((fileId) => byId.get(fileId));
        if (files.some((file) => !file)) {
          reject(new Error("Workspace has a missing file"));
          return;
        }
        lastWrite = {
          id,
          revision,
          files: new Map([...byId].map(([key, file]) => [key, { ...file }])),
        };
        knownRevisions.set(id, revision);
        resolve({ ...workspace, files: files as PersistedFile[] });
      };
    });
  },
  async putWorkspace(w: WorkspaceRecord, options?: { rejectStale?: boolean }): Promise<void> {
    // Snapshot metadata before awaiting; callers may rename/move files in place.
    const files = w.files.map((file) => ({ ...file }));
    const { files: _files, ...metadata } = w;
    const revision = crypto.randomUUID();
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction([STORE, FILES, SUMMARIES], "readwrite");
      const current = tx.objectStore(STORE).get(w.id);
      current.onsuccess = () => {
        try {
          const previous = current.result as StoredWorkspace | undefined;
          // A conversion must not write an old UI snapshot over changes from
          // another tab (or recreate a workspace that another tab deleted).
          if (
            options?.rejectStale &&
            (!previous || knownRevisions.get(w.id) !== previous.revision)
          ) {
            throw new WorkspaceConflictError();
          }
          const cached =
            lastWrite?.id === w.id && lastWrite.revision === previous?.revision
              ? lastWrite.files
              : undefined;
          const fileStore = tx.objectStore(FILES);
          const nextIds = new Set(files.map((file) => file.id));
          for (const id of previous?.fileIds ?? []) {
            if (!nextIds.has(id)) fileStore.delete([w.id, id]);
          }
          for (const file of files) {
            if (!sameFile(cached?.get(file.id), file))
              fileStore.put({ ...file, workspaceId: w.id });
          }
          tx.objectStore(STORE).put({
            ...metadata,
            fileIds: files.map((file) => file.id),
            revision,
          });
          tx.objectStore(SUMMARIES).put(summaryOf({ ...w, files }));
        } catch (error) {
          tx.abort();
          reject(error);
        }
      };
      tx.onabort = () => reject(tx.error ?? new Error("Could not save workspace"));
      tx.oncomplete = () => {
        lastWrite = { id: w.id, revision, files: new Map(files.map((file) => [file.id, file])) };
        knownRevisions.set(w.id, revision);
        resolve();
      };
    });
  },
  async deleteWorkspace(id: string): Promise<void> {
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction([STORE, FILES, SUMMARIES], "readwrite");
      const cursor = tx.objectStore(FILES).index("workspaceId").openKeyCursor(id);
      cursor.onsuccess = () => {
        const row = cursor.result;
        if (!row) return;
        tx.objectStore(FILES).delete(row.primaryKey);
        row.continue();
      };
      tx.objectStore(STORE).delete(id);
      tx.objectStore(SUMMARIES).delete(id);
      tx.onabort = () => reject(tx.error ?? new Error("Could not delete workspace"));
      tx.oncomplete = () => {
        if (lastWrite?.id === id) lastWrite = null;
        knownRevisions.delete(id);
        resolve();
      };
    });
  },
  listWorkspaceSummaries() {
    return request<WorkspaceSummary[]>("readonly", (s) => s.getAll(), SUMMARIES);
  },
  async listWorkspaces(): Promise<WorkspaceRecord[]> {
    const list = await persistence.listWorkspaceSummaries();
    const workspaces = await Promise.all(list.map((w) => persistence.getWorkspace(w.id)));
    return workspaces.filter((w): w is WorkspaceRecord => !!w);
  },
  async clearAll(): Promise<void> {
    knownRevisions.clear();
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction([STORE, FILES, SUMMARIES], "readwrite");
      for (const store of [STORE, FILES, SUMMARIES]) tx.objectStore(store).clear();
      tx.onabort = () => reject(tx.error ?? new Error("Could not clear storage"));
      tx.oncomplete = () => {
        lastWrite = null;
        resolve();
      };
    });
  },
  destroy() {
    return deleteDatabase();
  },
};

// ---- scroll position (localStorage, per workspace) ----
//
// Scroll position used to ride along in the workspace record, which meant every
// scroll-stop wrote the entire workspace back to IndexedDB — every document's
// text plus every binary file's base64 data URL, structured-cloned in one go.
// In a workspace holding a few PDFs that is tens of megabytes of copying on the
// main thread, every time the reader stopped scrolling.
//
// It is one number. It lives in localStorage now, keyed per workspace, and the
// workspace record is only written when the workspace itself actually changes.
// `WorkspaceRecord.ui.scrollTop` is still populated on save so exports and
// share links keep working.

const SCROLL_KEY_PREFIX = "localdox:scroll:";

export function saveScrollTop(workspaceId: string, top: number): void {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.setItem(SCROLL_KEY_PREFIX + workspaceId, String(Math.round(top)));
  } catch {
    /* storage unavailable — the position is simply not restored next time */
  }
}

export function loadScrollTop(workspaceId: string): number | null {
  if (typeof localStorage === "undefined") return null;
  try {
    const raw = localStorage.getItem(SCROLL_KEY_PREFIX + workspaceId);
    if (raw == null) return null;
    const n = Number(raw);
    return Number.isFinite(n) && n >= 0 ? n : null;
  } catch {
    return null;
  }
}

export function emptyUI(): PersistedUI {
  return {
    activeFileId: null,
    expanded: {},
    sidebarCollapsed: false,
    scrollTop: 0,
    fileOrder: [],
    recentFileIds: [],
    panes: [],
    focusedPaneId: null,
  };
}

export function newWorkspaceRecord(name: string): WorkspaceRecord {
  const now = Date.now();
  return {
    id: crypto.randomUUID(),
    name,
    createdAt: now,
    updatedAt: now,
    files: [],
    folders: [],
    bookmarks: [],
    saved: [],
    highlights: [],
    ui: emptyUI(),
  };
}

// ---- lightweight preferences (localStorage) ----

// One light and one dark palette, both WCAG-checked (see styles.css). The set
// was five; sepia/nord/black were dropped so there is one obvious choice per
// ambient light level rather than three near-identical dark variants.
export type ThemePref = "light" | "dark";

// Themes whose surfaces are dark — used to keep the legacy `.dark` class in sync
// so dark-only rules (code highlighting, katex, mermaid) still apply.
export const DARK_THEMES: readonly ThemePref[] = ["dark"];
export const READER_THEMES: readonly ThemePref[] = ["light", "dark"];

export function isDarkTheme(theme: ThemePref): boolean {
  return DARK_THEMES.includes(theme);
}

/** Stored prefs predating the trim name themes that no longer exist. Map each
 *  to whichever survivor matches its brightness, so an existing reader's screen
 *  does not invert under them. */
function migrateTheme(theme: unknown): ThemePref {
  if (theme === "light" || theme === "dark") return theme;
  if (theme === "sepia") return "light";
  if (theme === "nord" || theme === "black") return "dark";
  return DEFAULT_PREFS.theme;
}

// How a multi-section markdown document is laid out for reading.
// "paginated" = one section per page with prev/next; "single" = whole doc scrolls.
export type ReadingMode = "paginated" | "single";

// Reading typeface. Each maps to a --font-body / --font-heading pair in styles.css.
// One built-in face — Atkinson Hyperlegible, drawn for maximum letterform
// distinction — plus whatever the reader uploads themselves. The other bundled
// families were dropped: picking between five similar faces is not a decision
// worth putting in front of someone who wants to read.
export type ReadingFont = "hyperlegible" | "custom" | "google";
export const READING_FONTS: readonly ReadingFont[] = ["hyperlegible", "custom", "google"];

/** Old prefs name faces that are no longer bundled. They all collapse onto the
 *  one remaining built-in; "custom" only survives if a font is actually stored,
 *  and "google" only if a family name was saved alongside it — both of which
 *  the caller checks separately. */
function migrateFont(font: unknown): ReadingFont {
  if (font === "custom") return "custom";
  if (font === "google") return "google";
  return "hyperlegible";
}

export interface Prefs {
  theme: ThemePref;
  /**
   * Colour diagram nodes by what they mean — green for success, red for
   * failure, amber for a decision — rather than leaving every box the same
   * neutral fill. Applies to Raw and Stepped; Flow keeps the animator's own
   * palette, which already colours by packet.
   */
  diagramColors: boolean;
  /**
   * Let Stepped diagrams move the camera: close in on the part being drawn,
   * glide between parts, and pull back to the whole at the end. Off keeps the
   * whole diagram framed throughout. Reduced-motion system settings also hold
   * it still, whatever this says.
   */
  diagramCamera: boolean;
  /**
   * Stepped diagrams play arrows the author numbered (`A -->|1| B`) in that
   * order first. Off walks every diagram in the automatic order.
   */
  diagramFollowNumbers: boolean;
  /** Stepped diagrams show each arrow's step number on it as it is drawn. */
  diagramNumbers: boolean;
  /**
   * Whether the AI features exist at all.
   *
   * Off hides every AI surface — the Ask AI panel and its sidebar entry, the
   * Ask AI row on the selection popover, the settings tab — rather than
   * greying them out. A reader who does not want AI in their reader should not
   * have to look at it.
   */
  aiEnabled: boolean;
  /** Show uploaded attachment folders in the sidebar. Files remain available when hidden. */
  showEmbedMedia: boolean;
  lastWorkspaceId: string | null;
  // The reader's name, asked once and remembered for personalized greetings.
  name: string | null;
  // True once the reader has answered the name prompt (set a name or skipped),
  // so the greeting modal never asks again.
  namePrompted: boolean;
  readingMode: ReadingMode;
  readingFont: ReadingFont;
  /**
   * The Google Fonts family backing `readingFont: "google"`.
   *
   * Only the name is kept — the face itself is fetched from Google's CDN on
   * boot. Null whenever the reader has never named one, which is also what
   * makes the "google" choice inert until they do.
   */
  googleFont: string | null;
  /**
   * Which engine typesets math.
   *
   * "auto" is KaTeX with a MathJax fallback for what KaTeX cannot draw, and is
   * right for nearly everyone. "mathjax" forces the high-coverage engine for a
   * document full of exotic LaTeX; "temml" renders to MathML, which some screen
   * readers navigate better than KaTeX's HTML. See `src/services/math/renderer.ts`.
   */
  mathRenderer: MathRendererType;
  /** Number display equations and resolve `\ref`/`\eqref` against them. */
  mathNumbering: boolean;
  /**
   * MathJax's accessibility explorer: keyboard navigation of an expression's
   * sub-tree, with each part spoken. Loads a speech-rule engine on first use,
   * so it is opt-in.
   */
  mathExplorer: boolean;
  /**
   * How wide the reading/editing column gets, as a percentage of the space
   * available next to the sidebar.
   *
   * Because it is a percentage of that space rather than a fixed pixel width,
   * it already tracks the sidebar being collapsed or expanded on its own —
   * only the slider itself needs a setting. 100 fills all the available
   * width; the low end keeps a narrow, book-like column.
   */
  contentWidth: number;
}

/** The column can't get narrower than this, or wider than this. */
export const CONTENT_WIDTH_MIN = 40;
export const CONTENT_WIDTH_MAX = 100;

function clampContentWidth(value: unknown): number {
  const n = typeof value === "number" && Number.isFinite(value) ? value : DEFAULT_PREFS.contentWidth;
  return Math.min(CONTENT_WIDTH_MAX, Math.max(CONTENT_WIDTH_MIN, n));
}

const PREFS_KEY = "localdox:prefs";
const DEFAULT_PREFS: Prefs = {
  theme: "dark",
  diagramColors: true,
  diagramCamera: true,
  diagramFollowNumbers: true,
  diagramNumbers: true,
  aiEnabled: true,
  showEmbedMedia: true,
  lastWorkspaceId: null,
  name: null,
  namePrompted: false,
  readingMode: "paginated",
  readingFont: "hyperlegible",
  googleFont: null,
  mathRenderer: "auto",
  mathNumbering: true,
  mathExplorer: false,
  contentWidth: 50,
};

export function loadPrefs(): Prefs {
  if (typeof localStorage === "undefined") return { ...DEFAULT_PREFS };
  try {
    const raw = localStorage.getItem(PREFS_KEY);
    if (!raw) return { ...DEFAULT_PREFS };
    const stored = { ...DEFAULT_PREFS, ...JSON.parse(raw) };
    // Themes and faces were trimmed; a pref naming a removed one has to be
    // mapped on read or it would set a `data-theme` no stylesheet answers.
    return {
      ...stored,
      showEmbedMedia: stored.showEmbedMedia !== false,
      theme: migrateTheme(stored.theme),
      readingFont: migrateFont(stored.readingFont),
      contentWidth: clampContentWidth(stored.contentWidth),
    };
  } catch {
    return { ...DEFAULT_PREFS };
  }
}

export function savePrefs(patch: Partial<Prefs>): void {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.setItem(PREFS_KEY, JSON.stringify({ ...loadPrefs(), ...patch }));
  } catch {
    /* storage unavailable — preferences stay in memory */
  }
}

// ---- import / export (JSON) ----

export function serializeWorkspace(w: WorkspaceRecord): string {
  return JSON.stringify({ format: "localdox-workspace", version: 1, workspace: w }, null, 2);
}

/** Parse an exported workspace JSON into a fresh record (new id, no clobber). */
export function parseWorkspaceImport(json: string): WorkspaceRecord {
  const data = JSON.parse(json);
  const w = data?.workspace ?? data;
  if (!w || !Array.isArray(w.files)) {
    throw new Error("Not a valid workspace file");
  }
  const now = Date.now();
  return {
    id: crypto.randomUUID(),
    name: typeof w.name === "string" && w.name.trim() ? w.name : "Imported workspace",
    createdAt: typeof w.createdAt === "number" ? w.createdAt : now,
    updatedAt: now,
    files: w.files
      .filter((f: any) => f && typeof f.content === "string")
      .map((f: any) => ({
        id: typeof f.id === "string" ? f.id : crypto.randomUUID(),
        name: typeof f.name === "string" ? f.name : "untitled.md",
        content: f.content,
        data: typeof f.data === "string" ? f.data : undefined,
        mimeType: typeof f.mimeType === "string" ? f.mimeType : undefined,
        size: typeof f.size === "number" ? f.size : undefined,
        addedAt: typeof f.addedAt === "number" ? f.addedAt : undefined,
        kind: typeof f.kind === "string" ? f.kind : undefined,
        derivedFrom: parseDerivation(f.derivedFrom),
        folderId: typeof f.folderId === "string" ? f.folderId : null,
      })),
    folders: Array.isArray(w.folders)
      ? (w.folders as Partial<FolderRecord & { parentId?: unknown }>[])
          .filter((f) => f && typeof f.id === "string" && typeof f.name === "string")
          .map((f) => ({
            purpose: f.purpose === "embed-media" ? "embed-media" as const : undefined,
            id: f.id as string,
            name: f.name as string,
            createdAt: typeof f.createdAt === "number" ? f.createdAt : now,
            // Nesting has to survive a share link or a re-import. Dropping this
            // would silently flatten every subfolder into the top level.
            parentId: typeof f.parentId === "string" ? f.parentId : null,
          }))
      : [],
    bookmarks: Array.isArray(w.bookmarks)
      ? w.bookmarks.filter((b: any) => typeof b === "string")
      : [],
    highlights: Array.isArray(w.highlights) ? w.highlights : [],
    ui: {
      activeFileId: typeof w.ui?.activeFileId === "string" ? w.ui.activeFileId : null,
      expanded: typeof w.ui?.expanded === "object" ? w.ui.expanded : {},
      sidebarCollapsed: typeof w.ui?.sidebarCollapsed === "boolean" ? w.ui.sidebarCollapsed : false,
      scrollTop: typeof w.ui?.scrollTop === "number" ? w.ui.scrollTop : 0,
      fileOrder: Array.isArray(w.ui?.fileOrder) ? w.ui.fileOrder : [],
      recentFileIds: Array.isArray(w.ui?.recentFileIds) ? w.ui.recentFileIds : [],
      // The split layout has to survive a reload or a share link. Dropping it
      // here would silently collapse every workspace back to one pane.
      panes: Array.isArray(w.ui?.panes)
        ? (w.ui.panes as Partial<PersistedPane>[])
            .filter((pane) => pane && typeof pane.id === "string" && Array.isArray(pane.tabs))
            .map((pane) => ({
              id: pane.id as string,
              tabs: (pane.tabs as unknown[]).filter((id): id is string => typeof id === "string"),
              activeTabId: typeof pane.activeTabId === "string" ? pane.activeTabId : null,
            }))
        : [],
      focusedPaneId: typeof w.ui?.focusedPaneId === "string" ? w.ui.focusedPaneId : null,
    },
  };
}

// Share links. Two shapes exist, both carrying only a short bytebin key in the
// URL so a large document survives being pasted into a chat client:
//
//   #share=<key>        a whole workspace — imported on load, no questions asked
//   #share-files=<key>  a hand-picked set of files — the recipient chooses
//                       between a new workspace and the one they are already in
//
// Older links carry the compressed payload inline instead of a key; `fetchShare`
// still reads those.

import type { PersistedFile } from "./persistence";
import { parseDerivation, remapDerivation } from "../../services/doc-conversion/types.ts";

const BYTEBIN_URL = "https://bytebin.lucko.me";

export const SHARE_HASH = "#share=";
export const SHARE_FILES_HASH = "#share-files=";

export interface SharedFilesPayload {
  format: "localdox-files";
  version: 1;
  /** Workspace the files came from — the default name for a new workspace. */
  sourceName: string;
  sharedAt: number;
  files: PersistedFile[];
}

export function serializeSharedFiles(files: PersistedFile[], sourceName: string): string {
  const includedIds = new Map(files.map((file) => [file.id, file.id]));
  const payload: SharedFilesPayload = {
    format: "localdox-files",
    version: 1,
    sourceName: sourceName?.trim() || "Shared files",
    sharedAt: Date.now(),
    files: files.map((f) => ({
      id: f.id,
      name: f.name,
      content: f.content,
      data: f.data,
      mimeType: f.mimeType,
      size: f.size,
      addedAt: f.addedAt,
      kind: f.kind,
      derivedFrom: remapDerivation(f.derivedFrom, includedIds),
    })),
  };
  return JSON.stringify(payload);
}

/** Parse a `#share-files=` payload. Throws when it isn't one. */
export function parseSharedFiles(json: string): SharedFilesPayload {
  const data = JSON.parse(json);
  if (!data || !Array.isArray(data.files)) throw new Error("Not a shared file link");
  const files: PersistedFile[] = data.files
    .filter((f: any) => f && typeof f.content === "string")
    .map((f: any) => ({
      id: typeof f.id === "string" ? f.id : crypto.randomUUID(),
      name: typeof f.name === "string" && f.name.trim() ? f.name : "untitled.md",
      content: f.content,
      data: typeof f.data === "string" ? f.data : undefined,
      mimeType: typeof f.mimeType === "string" ? f.mimeType : undefined,
      size: typeof f.size === "number" ? f.size : undefined,
      addedAt: typeof f.addedAt === "number" ? f.addedAt : undefined,
      kind: typeof f.kind === "string" ? f.kind : undefined,
      derivedFrom: parseDerivation(f.derivedFrom),
    }));
  if (files.length === 0) throw new Error("Shared link contains no readable files");
  return {
    format: "localdox-files",
    version: 1,
    sourceName:
      typeof data.sourceName === "string" && data.sourceName.trim()
        ? data.sourceName
        : "Shared files",
    sharedAt: typeof data.sharedAt === "number" ? data.sharedAt : Date.now(),
    files,
  };
}

/** Put a JSON payload on bytebin; returns the key that goes in the link hash. */
export async function uploadShare(json: string): Promise<string> {
  const res = await fetch(`${BYTEBIN_URL}/post`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json" },
    body: json,
  });
  if (!res.ok) throw new Error("Failed to upload share payload");
  const data = await res.json();
  if (!data?.key) throw new Error("Share upload returned no key");
  return data.key as string;
}

/**
 * Read what a share hash points at. Short values are bytebin keys; anything
 * longer is a legacy inline payload.
 */
export async function fetchShare(keyOrData: string): Promise<string> {
  if (keyOrData.length < 50) {
    const res = await fetch(`${BYTEBIN_URL}/${keyOrData}`);
    if (!res.ok) throw new Error("Failed to fetch from bytebin");
    return res.text();
  }
  return decodeAndDecompress(keyOrData);
}

/** Clipboard write with a fallback for browsers/contexts without the async API. */
export async function copyText(text: string): Promise<void> {
  try {
    await navigator.clipboard.writeText(text);
    return;
  } catch {
    // Insecure context or a denied permission — fall through to the old trick.
  }
  const field = document.createElement("textarea");
  field.value = text;
  field.setAttribute("readonly", "");
  field.style.position = "fixed";
  field.style.opacity = "0";
  document.body.appendChild(field);
  field.select();
  try {
    document.execCommand("copy");
  } finally {
    document.body.removeChild(field);
  }
}

export function copyLink(url: string): Promise<void> {
  return copyText(url);
}

export function base64UrlEncode(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer);
  let binary = "";
  for (let i = 0; i < bytes.byteLength; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  const base64 = btoa(binary);
  // Convert standard base64 to base64url
  return base64.replace(/\+/g, "-").replace(/\//g, "_").replace(/=/g, "");
}

export function base64UrlDecode(base64Url: string): Uint8Array {
  // Convert base64url to standard base64
  let base64 = base64Url.replace(/-/g, "+").replace(/_/g, "/");
  // Pad with '='
  while (base64.length % 4) {
    base64 += "=";
  }
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

export async function compressAndEncode(jsonStr: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(jsonStr);

  const cs = new CompressionStream("deflate-raw");
  const writer = cs.writable.getWriter();
  writer.write(data);
  writer.close();

  const response = new Response(cs.readable);
  const compressedBuffer = await response.arrayBuffer();

  return base64UrlEncode(compressedBuffer);
}

export async function decodeAndDecompress(encodedStr: string): Promise<string> {
  const compressedData = base64UrlDecode(encodedStr);

  const ds = new DecompressionStream("deflate-raw");
  const writer = ds.writable.getWriter();
  writer.write(compressedData as any);
  writer.close();

  const response = new Response(ds.readable);
  const decompressedBuffer = await response.arrayBuffer();

  const decoder = new TextDecoder();

  return decoder.decode(decompressedBuffer);
}

/**
 * Which diagrams the GPU engine draws instead of Mermaid's SVG.
 *
 * Flowcharts, ER, class and state diagrams, and only large ones. Below the threshold Mermaid's own SVG
 * is the better picture: exact shapes, theming, semantic colouring, subgraph
 * boxes — and at a few hundred nodes it lays out in well under a second and
 * animates at 60fps. Past it, the same pipeline measured 1.5s at 1,000 nodes,
 * 40s at 5,000 and never finishes at 10,000, with playback falling to 2fps.
 * That is the range where a WebAssembly layout and a WebGL renderer trade a
 * little fidelity for a diagram that appears at all.
 *
 * This runs on every source change, so it only scans text and never imports
 * Mermaid or the engine.
 */
import {
  scanDiagramSource,
  shouldUseDiagramPerformanceMode,
} from "../mermaid-performance.ts";
import type { DiagramKind } from "./flowchart.ts";

/** Edge lines at which a flowchart moves to the GPU engine. */
export const GPU_EDGE_THRESHOLD = 600;
/** Node-ish lines, for flowcharts that declare many nodes and few edges. */
export const GPU_LINE_THRESHOLD = 900;

const FLOWCHART_HEADER = /^(?:flowchart|graph)(?:\s+(TB|TD|BT|LR|RL))?\s*;?\s*$/i;

/** Structure thresholds for ER, class and state diagrams, where rows add up. */
export const GPU_ENTITY_THRESHOLD = 60;
export const GPU_ATTRIBUTE_THRESHOLD = 700;
export const GPU_RELATION_THRESHOLD = 300;

/** The first meaningful line: skips front matter, blank lines and comments. */
function headerLine(source: string): string | null {
  let inFrontMatter = false;
  let start = 0;
  for (let lines = 0; lines < 200 && start <= source.length; lines++) {
    const end = source.indexOf("\n", start);
    const line = source.slice(start, end < 0 ? source.length : end).trim();
    start = end < 0 ? source.length + 1 : end + 1;
    if (line === "---") {
      inFrontMatter = !inFrontMatter;
      continue;
    }
    if (inFrontMatter || !line || line.startsWith("%%")) continue;
    return line;
  }
  return null;
}

/** The flowchart header's direction, or null when this isn't a flowchart. */
export function flowchartDirection(source: string): string | null {
  const line = headerLine(source);
  const match = line ? FLOWCHART_HEADER.exec(line) : null;
  return match ? (match[1] ?? "TB").toUpperCase() : null;
}

/** Which kind of diagram the engine can draw this is, or null. */
export function diagramKind(source: string): DiagramKind | null {
  const line = headerLine(source);
  if (!line) return null;
  if (FLOWCHART_HEADER.test(line)) return "flowchart";
  const word = line.split(/\s/)[0];
  if (word === "erDiagram") return "er";
  if (word === "classDiagram" || word === "classDiagram-v2") return "class";
  if (word === "stateDiagram" || word === "stateDiagram-v2") return "state";
  return null;
}

export function shouldUseGpuEngine(source: string): boolean {
  const kind = diagramKind(source);
  if (!kind) return false;
  if (shouldUseDiagramPerformanceMode(source)) return true;
  const scan = scanDiagramSource(source);
  if (kind === "flowchart") {
    return scan.edges >= GPU_EDGE_THRESHOLD || scan.lines >= GPU_LINE_THRESHOLD;
  }
  return (
    scan.edges >= GPU_RELATION_THRESHOLD ||
    scan.entities >= GPU_ENTITY_THRESHOLD ||
    scan.attributes >= GPU_ATTRIBUTE_THRESHOLD ||
    scan.lines >= GPU_LINE_THRESHOLD
  );
}

import { useCallback, useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import {
  canConvertToMarkdown,
  CONVERSION_TIMEOUT_MS,
  describeConversionError,
  sameSource,
} from "./types";
import type { ConversionFailure, ConversionResult, ConversionSource } from "./types";

export function useDocumentConversion({
  workspaceId,
  files,
  commit,
}: {
  workspaceId: string | null;
  files: ConversionSource[];
  commit: (
    source: ConversionSource,
    result: ConversionResult,
    workspaceId: string,
  ) => Promise<void>;
}) {
  const [runningId, setRunningId] = useState<string | null>(null);
  const committing = useRef(false);
  const current = useRef({ workspaceId, files, commit });
  current.current = { workspaceId, files, commit };
  const job = useRef<{
    worker: Worker;
    source: ConversionSource;
    workspaceId: string;
    timer: ReturnType<typeof setTimeout>;
  } | null>(null);
  const cancel = useCallback(() => {
    if (!job.current) return;
    job.current.worker.terminate();
    clearTimeout(job.current.timer);
    job.current = null;
    setRunningId(null);
    toast.dismiss("document-conversion");
  }, []);
  useEffect(() => cancel, [workspaceId, cancel]);
  useEffect(() => {
    if (
      job.current &&
      !sameSource(
        files.find((f) => f.id === job.current?.source.id),
        job.current.source,
      )
    )
      cancel();
  }, [files, cancel]);

  const start = useCallback(
    (id: string) => {
      if (job.current || committing.current) {
        toast.info("A conversion is already running. Cancel it before starting another.");
        return;
      }
      const { files, workspaceId } = current.current;
      const source = files.find((file) => file.id === id);
      if (!workspaceId || !source || !canConvertToMarkdown(source)) return;
      try {
        const worker = new Worker(
          new URL("./conversion.worker.ts", import.meta.url),
          { type: "module" },
        );
        const fail = (error: ConversionFailure) => {
          if (job.current?.worker !== worker) return;
          cancel();
          toast.error(describeConversionError(error), { duration: 10000 });
        };
        const timer = setTimeout(() => fail({ code: "timeout" }), CONVERSION_TIMEOUT_MS);
        job.current = { worker, source: { ...source }, workspaceId, timer };
        setRunningId(id);
        toast.loading(`Converting ${source.name} on this device…`, {
          id: "document-conversion",
          description: "Text, tables, and links. Embedded images remain in the original.",
          action: { label: "Cancel", onClick: cancel },
        });
        worker.onerror = () => fail({ code: "startup" });
        worker.onmessage = async (
          event: MessageEvent<{ result?: ConversionResult; error?: ConversionFailure }>,
        ) => {
          if (job.current?.worker !== worker) return;
          if (event.data.error) return fail(event.data.error);
          const result = event.data.result;
          if (!result) return fail({ code: "unknown" });
          cancel();
          if (
            current.current.workspaceId !== workspaceId ||
            !sameSource(
              current.current.files.find((f) => f.id === id),
              source,
            )
          )
            return;
          try {
            committing.current = true;
            setRunningId(id);
            await current.current.commit(source, result, workspaceId);
          } catch (error) {
            toast.error(
              error instanceof Error
                ? error.message
                : "Could not save the Markdown copy. The original is unchanged.",
            );
          } finally {
            committing.current = false;
            setRunningId(null);
          }
        };
        worker.postMessage({
          id: source.id,
          name: source.name,
          content: source.content,
          data: source.data,
        });
      } catch {
        cancel();
        toast.error(describeConversionError({ code: "startup" }));
      }
    },
    [cancel],
  );
  return { runningId, start, cancel };
}

// Document-wide math state, shared with every equation in the tree.
//
// Passed on context rather than through props for the same reason the viewer's
// saved-items context exists: equations are rendered deep inside markdown by
// react-markdown's component map, and threading state through that map would
// rebuild every renderer — and therefore re-render the whole document — every
// time any of this changed.

import { createContext, useContext, useMemo, type ReactNode } from "react";
import {
  buildEquationRegistry,
  EMPTY_EQUATION_REGISTRY,
  type EquationRegistry,
} from "./equation-registry";
import { DEFAULT_MATH_PREFERENCES, type MathPreferences } from "./types";

export interface MathContextValue {
  registry: EquationRegistry;
  preferences: MathPreferences;
  /**
   * Jump to an equation by label — what a clicked `\eqref` does.
   *
   * Supplied by the viewer, which is the only thing that knows how to reach an
   * equation that is in a different section of a paginated document.
   */
  navigateToEquation?: (label: string) => void;
}

const MathContext = createContext<MathContextValue>({
  registry: EMPTY_EQUATION_REGISTRY,
  preferences: DEFAULT_MATH_PREFERENCES,
});

export function useMathContext(): MathContextValue {
  return useContext(MathContext);
}

/**
 * Builds the registry for one document and publishes it.
 *
 * The registry is numbered from `source`, so it must be the *whole* document's
 * markdown even when only one section is on screen — otherwise equation 12
 * renumbers itself to 1 the moment the reader pages to its section. In
 * paginated mode the viewer passes the full document text here while rendering
 * a single chunk, which is exactly what keeps numbering stable.
 */
export function MathProvider({
  source,
  preferences = DEFAULT_MATH_PREFERENCES,
  navigateToEquation,
  children,
}: {
  source: string;
  preferences?: MathPreferences;
  navigateToEquation?: (label: string) => void;
  children: ReactNode;
}) {
  const registry = useMemo(
    () => buildEquationRegistry(source, { numbering: preferences.numberEquations }),
    [source, preferences.numberEquations],
  );

  const value = useMemo<MathContextValue>(
    () => ({ registry, preferences, navigateToEquation }),
    [registry, preferences, navigateToEquation],
  );

  return <MathContext.Provider value={value}>{children}</MathContext.Provider>;
}

// The hook that turns LaTeX into markup, and the one place that decides
// whether an equation paints now or after an await.

import { useEffect, useState } from "react";
import {
  isMathRenderError,
  peekRenderedMath,
  renderMath,
  renderMathSync,
} from "./renderer";
import type { MathRenderError, MathRendererType, RenderedMath } from "./types";

export type MathRenderState =
  | { status: "ready"; result: RenderedMath }
  | { status: "pending" }
  | { status: "error"; error: MathRenderError };

/**
 * Typeset one expression.
 *
 * Two paths, and which one runs decides whether the document paints in one
 * commit or two:
 *
 *  - The fast path is synchronous and taken during render. Once KaTeX's module
 *    is resident, a KaTeX-renderable expression is already markup by the time
 *    this returns, so a document full of equations paints once with all of
 *    them present.
 *  - Everything else — the first equations of a session (KaTeX is loaded on
 *    demand, so a reader with no math never downloads it), an `align`
 *    environment needing MathJax, a Temml preference — goes through the effect
 *    and paints itself a moment later. Never the document; just that equation.
 */
export function useMathRender(
  latex: string,
  displayMode: boolean,
  renderer: MathRendererType = "auto",
): MathRenderState {
  // Attempted during render, not in an effect. `renderMathSync` is pure with
  // respect to React — it reads and writes a module-level cache and touches no
  // DOM — and doing it here is the difference between one commit and two.
  const immediate = renderMathSync({ latex, displayMode, renderer });

  const [state, setState] = useState<MathRenderState>(() =>
    immediate ? { status: "ready", result: immediate } : { status: "pending" },
  );

  useEffect(() => {
    // Already settled for this exact expression by a synchronous render or an
    // earlier pass — nothing to do, and no placeholder to flash.
    const cached = peekRenderedMath(latex, displayMode, renderer);
    if (cached) {
      setState((previous) =>
        previous.status === "ready" && previous.result === cached
          ? previous
          : { status: "ready", result: cached },
      );
      return;
    }

    // Deliberately *not* guarded by a ref holding "the expression the state
    // describes". That guard deadlocked under React's double-invoked effects:
    // the first pass marked the expression as handled and was then torn down,
    // and the second pass saw the mark and never started the render at all —
    // leaving the equation on its placeholder for good. The cache above is the
    // correct guard: it is keyed by the work rather than by the attempt, so a
    // second pass either finds the result or redoes work that is idempotent.
    let alive = true;
    setState((previous) => (previous.status === "pending" ? previous : { status: "pending" }));

    renderMath({ latex, displayMode, renderer })
      .then((result) => {
        if (alive) setState({ status: "ready", result });
      })
      .catch((error: unknown) => {
        if (!alive) return;
        setState({
          status: "error",
          error: isMathRenderError(error)
            ? error
            : {
                latex,
                displayMode,
                message: error instanceof Error ? error.message : String(error),
                attempted: [],
              },
        });
      });

    return () => {
      alive = false;
    };
  }, [latex, displayMode, renderer]);

  // A synchronous result always wins over state that describes something else:
  // when `latex` changes to an expression KaTeX can draw, the markup exists
  // before the effect has had a chance to run.
  if (immediate && (state.status !== "ready" || state.result.latex !== latex)) {
    return { status: "ready", result: immediate };
  }
  return state;
}

