// Unit tests for the export parser.
//
// This is the layer both writers read a document through, so a mistake here is
// a mistake in the `.docx` *and* the PDF at once — and neither is easy to eye
// against a source file once it is a binary or a print preview. The DOCX and
// print writers themselves need a DOM (canvas, an iframe, Mermaid's renderer)
// and are exercised in the browser; everything that decides *what* ends up in
// the document is pure and is covered here.
//
// The cases that matter most are the ones that used to be silently wrong in a
// hand-rolled markdown reader: a mermaid fence recognised as a diagram rather
// than as code, emphasis boundaries that eat their spaces, `snake_case` read as
// italics, and a table whose rows do not match its header.

import assert from "node:assert/strict";
import { test } from "node:test";

import {
  columnWidthDemand,
  parseInline,
  parseMarkdownBlocks,
  runsToText,
  type ExportBlock,
} from "../src/services/markdown-export/markdown-ast.ts";

function only<T extends ExportBlock["type"]>(
  source: string,
  type: T,
): Extract<ExportBlock, { type: T }> {
  const blocks = parseMarkdownBlocks(source);
  assert.equal(blocks.length, 1, `expected one block, got ${blocks.map((b) => b.type).join(", ")}`);
  assert.equal(blocks[0].type, type);
  return blocks[0] as Extract<ExportBlock, { type: T }>;
}

test("a mermaid fence is a diagram, not a code block", () => {
  const block = only("```mermaid\ngraph TD;\n  A-->B;\n```", "mermaid");
  assert.equal(block.code, "graph TD;\n  A-->B;");
});

test("the mmd alias is also a diagram", () => {
  assert.equal(only("```mmd\npie\n```", "mermaid").code, "pie");
});

test("a non-mermaid fence keeps its language and stays code", () => {
  const block = only("```ts\nconst a = 1;\n```", "code");
  assert.equal(block.language, "ts");
  assert.equal(block.text, "const a = 1;");
});

test("a fence containing backticks is closed by its own marker length", () => {
  const block = only("````\n```\nnested\n```\n````", "code");
  assert.equal(block.text, "```\nnested\n```");
});

test("headings carry their level and drop closing hashes", () => {
  const block = only("### Results ###", "heading");
  assert.equal(block.level, 3);
  assert.equal(runsToText(block.runs), "Results");
});

test("a setext underline is a heading, not a rule", () => {
  const blocks = parseMarkdownBlocks("Overview\n---\n");
  assert.equal(blocks.length, 1);
  assert.equal(blocks[0].type, "heading");
  assert.equal(blocks[0].type === "heading" && blocks[0].level, 2);
});

test("a bare rule with no text above it stays a rule", () => {
  assert.equal(parseMarkdownBlocks("text\n\n---\n\nmore")[1].type, "rule");
});

test("front matter is dropped rather than printed as a table", () => {
  const blocks = parseMarkdownBlocks("---\ntitle: X\ntags: [a]\n---\n\n# Real\n");
  assert.equal(blocks.length, 1);
  assert.equal(blocks[0].type, "heading");
});

test("emphasis keeps the spaces around it", () => {
  // The bug this guards: flushing a run on a marker without preserving the
  // surrounding whitespace turns "a bold c" into "aboldc" in Word.
  assert.equal(runsToText(parseInline("a **bold** c")), "a bold c");
});

test("bold and italic are recorded as marks, not as literal asterisks", () => {
  const runs = parseInline("plain **b** _i_ ~~s~~");
  assert.equal(runs.find((r) => r.text === "b")?.bold, true);
  assert.equal(runs.find((r) => r.text === "i")?.italic, true);
  assert.equal(runs.find((r) => r.text === "s")?.strike, true);
});

test("an underscore inside a word is literal", () => {
  assert.equal(runsToText(parseInline("read snake_case_name here")), "read snake_case_name here");
  assert.ok(parseInline("read snake_case_name here").every((run) => !run.italic));
});

test("a code span suppresses emphasis inside it", () => {
  const runs = parseInline("use `a * b * c` here");
  const code = runs.find((run) => run.code);
  assert.equal(code?.text, "a * b * c");
});

test("links keep both label and target", () => {
  const [run] = parseInline("[docs](https://example.com/a)");
  assert.equal(run.text, "docs");
  assert.equal(run.href, "https://example.com/a");
});

test("an escaped marker is a literal character", () => {
  assert.equal(runsToText(parseInline("2 \\* 3 \\* 4")), "2 * 3 * 4");
});

test("nested list items carry their depth", () => {
  const block = only("- a\n  - b\n    - c\n", "list");
  assert.deepEqual(
    block.items.map((item) => [runsToText(item.runs), item.depth]),
    [
      ["a", 0],
      ["b", 1],
      ["c", 2],
    ],
  );
});

test("task items record their checked state and lose the brackets", () => {
  const block = only("- [x] done\n- [ ] todo\n", "list");
  assert.deepEqual(
    block.items.map((item) => [runsToText(item.runs), item.checked]),
    [
      ["done", true],
      ["todo", false],
    ],
  );
});

test("an ordered list is marked ordered", () => {
  assert.equal(only("1. one\n2. two\n", "list").ordered, true);
});

test("bullets nested under numbered steps keep their own marker", () => {
  // Otherwise the detail under step 2 renders as "a., b." in Word and as an
  // <ol> in print — an author's aside promoted to a sub-procedure.
  const block = only("1. First\n2. Second\n   - detail\n   - more\n3. Third\n", "list");
  assert.deepEqual(
    block.items.map((item) => [runsToText(item.runs), item.depth, item.ordered]),
    [
      ["First", 0, true],
      ["Second", 0, true],
      ["detail", 1, false],
      ["more", 1, false],
      ["Third", 0, true],
    ],
  );
});

test("numbered sub-steps under a bullet keep their own marker", () => {
  const block = only("- Setup\n  1. install\n  2. configure\n", "list");
  assert.deepEqual(
    block.items.map((item) => [item.depth, item.ordered]),
    [
      [0, false],
      [1, true],
      [1, true],
    ],
  );
});

test("every table row is padded to the header width", () => {
  // A short row is common in hand-written markdown and used to produce a row
  // with fewer cells than the header, which Word renders as a torn grid.
  const block = only("| a | b | c |\n|---|---|---|\n| 1 | 2 |\n", "table");
  assert.equal(block.header.length, 3);
  assert.equal(block.rows[0].length, 3);
  assert.deepEqual(block.rows[0].map(runsToText), ["1", "2", ""]);
});

test("an escaped pipe stays inside its cell", () => {
  const block = only("| a | b |\n|---|---|\n| x \\| y | z |\n", "table");
  assert.deepEqual(block.rows[0].map(runsToText), ["x | y", "z"]);
});

test("a blockquote parses its contents as blocks", () => {
  const block = only("> # Title\n> body\n", "quote");
  assert.deepEqual(
    block.blocks.map((inner) => inner.type),
    ["heading", "paragraph"],
  );
});

test("a diagram inside a blockquote is still a diagram", () => {
  const block = only("> ```mermaid\n> graph TD;\n> ```\n", "quote");
  assert.equal(block.blocks[0].type, "mermaid");
});

test("an image on its own line becomes an image block", () => {
  const block = only("![alt text](pic.png)", "image");
  assert.equal(block.src, "pic.png");
  assert.equal(block.alt, "alt text");
});

test("display math is a math block in both spellings", () => {
  assert.equal(only("$$\nE = mc^2\n$$", "math").tex, "E = mc^2");
  assert.equal(only("```math\nE = mc^2\n```", "math").tex, "E = mc^2");
});

test("consecutive paragraph lines join into one paragraph", () => {
  const block = only("one line\nand its continuation\n", "paragraph");
  assert.equal(runsToText(block.runs), "one line and its continuation");
});

test("a document round-trips its block order", () => {
  const source = [
    "# Title",
    "",
    "Intro paragraph.",
    "",
    "```mermaid",
    "graph LR; A-->B;",
    "```",
    "",
    "## Detail",
    "",
    "- one",
    "- two",
    "",
    "| k | v |",
    "|---|---|",
    "| a | 1 |",
    "",
    "> quoted",
    "",
    "---",
  ].join("\n");
  assert.deepEqual(
    parseMarkdownBlocks(source).map((block) => block.type),
    ["heading", "paragraph", "mermaid", "heading", "list", "table", "quote", "rule"],
  );
});

test("an unterminated fence does not swallow the rest of the document silently", () => {
  // It still consumes to the end — there is nothing else it could mean — but it
  // must produce a block rather than throwing or returning nothing.
  const blocks = parseMarkdownBlocks("# T\n\n```\nunclosed\n");
  assert.deepEqual(
    blocks.map((block) => block.type),
    ["heading", "code"],
  );
});

test("an empty document produces no blocks", () => {
  assert.deepEqual(parseMarkdownBlocks("   \n\n  \n"), []);
});

// Column widths. Both writers proportion tables through `columnWidthDemand`,
// and a wide table that Word renders as a wall of one-word lines is the exact
// failure this is here to prevent — so the relationships between columns are
// asserted rather than the numbers, which are free to be tuned.

const column = (header: string, ...cells: string[]) =>
  columnWidthDemand(parseInline(header), cells.map((cell) => parseInline(cell)));

test("a prose column is given more width than a short-value column", () => {
  const notes = column("Notes", "Migrated to the new pool last sprint; watch p99", "Rebuilding");
  const id = column("ID", "1", "2", "3");
  assert.ok(notes > id * 2, `expected the notes column to dwarf the id column (${notes} vs ${id})`);
});

test("a long header claims width even when its values are short", () => {
  // Otherwise "Error rate" wraps to two lines on every page of a long table
  // while the column sits half empty.
  assert.ok(column("Error rate", "0.01%", "1.2%") > column("Err", "0.01%", "1.2%"));
});

test("an unbreakable token sets a floor under the column", () => {
  // A column narrower than its longest word forces a mid-word break no matter
  // how many lines it gets.
  assert.ok(column("URL", "https://example.com/a/very/long/path") >= 36);
});

test("one outlier row does not take the width nine ordinary rows need", () => {
  const ordinary = Array.from({ length: 9 }, () => "ok");
  const withOutlier = column("Status", ...ordinary, "a".repeat(200));
  const without = column("Status", ...ordinary);
  assert.ok(
    withOutlier < without * 3,
    `one outlier should not triple the column (${without} -> ${withOutlier})`,
  );
});

test("prose width grows sub-linearly with length", () => {
  // Weighted by a square root: longer notes deserve more room, but not
  // proportionally more, or one prose column consumes the whole table.
  const short = column("Notes", "a".repeat(10).replace(/a/g, "x "));
  const long = column("Notes", "a".repeat(60).replace(/a/g, "x "));
  assert.ok(long > short);
  assert.ok(long < short * 6);
});

test("every column has a usable minimum", () => {
  assert.ok(column("#", "1") >= 4);
  assert.ok(column("", "") >= 4);
});

// What a multi-file selection can be exported as.
//
// The rule these cover is that a batch offers the *intersection* of what its
// documents can do, never the union. Offering Word for a selection that is half
// spreadsheets means half the export fails and the reader finds out by counting
// the files that arrived — so a mixed selection collapses to the original bytes
// and the menu says "Download" instead of "Export All".
//
// `exportDocuments` itself drives real downloads and belongs in the browser;
// what is pure — and what decides the menu the reader sees — is here.

import assert from "node:assert/strict";
import { test } from "node:test";

import {
  availableFormats,
  canConvert,
  isBatchable,
  sharedFormats,
  type ExportFormat,
} from "../src/services/markdown-export/index.ts";

const markdown = { kind: "markdown" as const, content: "# Hi" };
const text = { kind: "text" as const, content: "plain" };
const mermaid = { kind: "mermaid" as const, content: "graph TD; A-->B;" };
/** A document the app only reads: bytes, no markdown to convert. */
const spreadsheet = {
  kind: "spreadsheet" as const,
  content: "",
  data: "data:application/vnd.ms-excel;base64,AAAA",
};
const pdf = { kind: "pdf" as const, content: "", data: "data:application/pdf;base64,AAAA" };

test("a text-bearing document can be converted", () => {
  assert.equal(canConvert(markdown), true);
  assert.equal(canConvert(text), true);
  assert.equal(canConvert(mermaid), true);
});

test("a binary the app only reads cannot be converted", () => {
  assert.equal(canConvert(spreadsheet), false);
  assert.equal(canConvert(pdf), false);
});

test("an unconvertible document offers only its original bytes", () => {
  assert.deepEqual(availableFormats(spreadsheet), ["original"]);
});

test("a convertible document offers the writers plus the original", () => {
  const formats = availableFormats(markdown);
  assert.ok(formats.includes("docx"));
  assert.ok(formats.includes("pdf"));
  assert.ok(formats.includes("original"));
});

test("an empty selection offers nothing", () => {
  assert.deepEqual(sharedFormats([]), []);
});

test("a selection of convertible documents offers the conversions", () => {
  const formats = sharedFormats([markdown, text, mermaid]);
  assert.ok(formats.includes("docx"));
  assert.ok(formats.includes("markdown"));
  assert.ok(formats.length > 1, "more than one format means the menu says Export All");
});

test("one unconvertible document collapses the whole selection to Download", () => {
  // The intersection, not the union — this is the case the rule exists for.
  assert.deepEqual(sharedFormats([markdown, text, spreadsheet]), ["original"]);
  assert.deepEqual(sharedFormats([spreadsheet, pdf]), ["original"]);
});

test("a selection of one behaves like that document alone, minus batching", () => {
  assert.deepEqual(
    sharedFormats([markdown]),
    availableFormats(markdown).filter(isBatchable),
  );
});

test("PDF is not offered for a batch", () => {
  // It hands off to the browser's modal print dialog: a batch would queue one
  // dialog per file. An item that can only ever produce an error is worse than
  // no item, so it is filtered out rather than refused on click.
  assert.ok(!sharedFormats([markdown, text]).includes("pdf"));
  assert.equal(isBatchable("pdf"), false);
});

test("every other format batches", () => {
  const batchable: ExportFormat[] = ["docx", "markdown", "html", "original"];
  for (const format of batchable) assert.equal(isBatchable(format), true, format);
});

test("the single-document menu still offers PDF", () => {
  // Only the batch drops it; exporting one document through the print dialog
  // is the normal path and must stay available.
  assert.ok(availableFormats(markdown).includes("pdf"));
});

test("a mixed selection never offers more than one format", () => {
  // What the sidebar keys off: `formats.length > 1` is how it decides between
  // "Export All" with a submenu and a plain "Download Selected".
  assert.equal(sharedFormats([markdown, spreadsheet]).length, 1);
});

// Moving documents and folders between workspaces.
//
// A workspace is a closed world — file ids, folder ids, stars and highlights
// only mean anything inside the record that holds them — so a move is a
// transplant, and the ways it can quietly lose data are what these cover:
// a folder's descendants left behind, an id collision overwriting a document
// that was already there, and annotations dropped because they live beside the
// files rather than inside them.

import assert from "node:assert/strict";
import { test } from "node:test";

import {
  applyToDestination,
  expandFolderIds,
  planTransfer,
  removeFromSource,
  transferCounts,
} from "../src/lib/workspace/workspace-transfer.ts";
import type { FolderRecord, PersistedFile, WorkspaceRecord } from "../src/lib/workspace/persistence.ts";
import { closeFileEverywhere } from "../src/lib/workspace/panes.ts";
import type { PaneLayout } from "../src/lib/workspace/panes.ts";

const file = (id: string, folderId: string | null = null): PersistedFile => ({
  id,
  name: `${id}.md`,
  content: `# ${id}`,
  folderId,
});

const folder = (id: string, parentId: string | null = null): FolderRecord => ({
  id,
  name: id,
  createdAt: 0,
  parentId,
});

const workspace = (over: Partial<WorkspaceRecord> = {}): WorkspaceRecord => ({
  id: "ws",
  name: "Workspace",
  createdAt: 0,
  updatedAt: 0,
  files: [],
  folders: [],
  bookmarks: [],
  saved: [],
  highlights: [],
  ui: {
    activeFileId: null,
    expanded: {},
    sidebarCollapsed: false,
    scrollTop: 0,
    fileOrder: [],
  },
  ...over,
});

// --- folder expansion ---

test("a selected folder brings its whole subtree", () => {
  const folders = [folder("a"), folder("b", "a"), folder("c", "b"), folder("other")];
  assert.deepEqual([...expandFolderIds(folders, ["a"])].sort(), ["a", "b", "c"]);
});

test("an unrelated folder is left alone", () => {
  const folders = [folder("a"), folder("b", "a"), folder("other")];
  assert.ok(!expandFolderIds(folders, ["a"]).has("other"));
});

test("a parent cycle terminates instead of hanging", () => {
  // Not reachable through the UI, but a corrupted record should not spin.
  const folders = [folder("a", "b"), folder("b", "a")];
  assert.deepEqual([...expandFolderIds(folders, ["a"])].sort(), ["a", "b"]);
});

// --- what moves ---

test("a file inside a selected folder moves with it, unselected", () => {
  const source = workspace({
    files: [file("f1", "a"), file("f2", "b"), file("outside")],
    folders: [folder("a"), folder("b", "a")],
  });
  const plan = planTransfer(source, workspace(), { fileIds: [], folderIds: ["a"] });
  assert.deepEqual(
    plan.files.map((f) => f.id).sort(),
    ["f1", "f2"],
    "a nested folder's documents must come too",
  );
  assert.ok(!plan.removeFileIds.has("outside"));
});

test("a file picked out of a folder that stays behind lands at the top level", () => {
  // Its folder is not coming, so the id it pointed at does not exist in the
  // destination; keeping it would file the document into nothing.
  const source = workspace({ files: [file("f1", "a")], folders: [folder("a")] });
  const plan = planTransfer(source, workspace(), { fileIds: ["f1"], folderIds: [] });
  assert.equal(plan.files[0].folderId, null);
  assert.equal(plan.folders.length, 0);
});

test("a moved subtree keeps its internal shape", () => {
  const source = workspace({
    files: [file("f1", "b")],
    folders: [folder("a"), folder("b", "a")],
  });
  const plan = planTransfer(source, workspace(), { fileIds: [], folderIds: ["a"] });
  const a = plan.folders.find((f) => f.name === "a")!;
  const b = plan.folders.find((f) => f.name === "b")!;
  assert.equal(a.parentId, null, "the picked folder lands at the destination root");
  assert.equal(b.parentId, a.id, "its child still points at it");
  assert.equal(plan.files[0].folderId, b.id);
});

test("a landing folder re-parents the whole selection under it", () => {
  const source = workspace({ files: [file("f1")], folders: [folder("a")] });
  const plan = planTransfer(source, workspace(), { fileIds: ["f1"], folderIds: ["a"] }, "dest-1");
  assert.equal(plan.files[0].folderId, "dest-1");
  assert.equal(plan.folders[0].parentId, "dest-1");
});

// --- id collisions ---

test("a colliding file id is reassigned rather than overwriting the destination", () => {
  const source = workspace({ files: [file("dup")] });
  const destination = workspace({ files: [file("dup")] });
  const plan = planTransfer(source, destination, { fileIds: ["dup"], folderIds: [] });
  assert.notEqual(plan.files[0].id, "dup");
  assert.equal(plan.renamedFileIds.get("dup"), plan.files[0].id);
  // The source still knows it by the original id, or it could not be removed.
  assert.ok(plan.removeFileIds.has("dup"));
});

test("a non-colliding id is kept, so a move and a move back is the same document", () => {
  const source = workspace({ files: [file("f1")] });
  const plan = planTransfer(source, workspace(), { fileIds: ["f1"], folderIds: [] });
  assert.equal(plan.files[0].id, "f1");
});

test("a colliding folder id is reassigned and its children follow the new id", () => {
  const source = workspace({
    files: [file("f1", "dup")],
    folders: [folder("dup"), folder("child", "dup")],
  });
  const destination = workspace({ folders: [folder("dup")] });
  const plan = planTransfer(source, destination, { fileIds: [], folderIds: ["dup"] });
  const moved = plan.folders.find((f) => f.name === "dup")!;
  assert.notEqual(moved.id, "dup");
  assert.equal(plan.folders.find((f) => f.name === "child")!.parentId, moved.id);
  assert.equal(plan.files[0].folderId, moved.id);
});

// --- annotations ---

test("stars and highlights travel with their document", () => {
  const source = workspace({
    files: [file("f1"), file("f2")],
    saved: [
      { id: "s1", fileId: "f1", kind: "file", title: "x", createdAt: 0 },
      { id: "s2", fileId: "f2", kind: "file", title: "y", createdAt: 0 },
    ],
    highlights: [{ id: "h1", fileId: "f1", text: "t", color: "yellow" }],
  });
  const plan = planTransfer(source, workspace(), { fileIds: ["f1"], folderIds: [] });
  assert.deepEqual(
    plan.saved.map((s) => s.id),
    ["s1"],
    "only the moved document's stars come across",
  );
  assert.equal(plan.highlights.length, 1);
});

test("annotations are rewritten when their file id is reassigned", () => {
  // The case that silently loses a reader's work: the file is renumbered to
  // dodge a collision and its stars keep pointing at an id that no longer
  // exists in either workspace.
  const source = workspace({
    files: [file("dup")],
    saved: [{ id: "s1", fileId: "dup", kind: "file", title: "x", createdAt: 0 }],
    highlights: [{ id: "h1", fileId: "dup", text: "t", color: "yellow" }],
  });
  const destination = workspace({ files: [file("dup")] });
  const plan = planTransfer(source, destination, { fileIds: ["dup"], folderIds: [] });
  const newId = plan.files[0].id;
  assert.equal(plan.saved[0].fileId, newId);
  assert.equal(plan.highlights[0].fileId, newId);
});

// --- applying ---

test("the destination keeps what it had and gains what moved", () => {
  const source = workspace({ files: [file("f1")] });
  const destination = workspace({ files: [file("existing")], ui: { ...workspace().ui, fileOrder: ["existing"] } });
  const plan = planTransfer(source, destination, { fileIds: ["f1"], folderIds: [] });
  const next = applyToDestination(destination, plan);
  assert.deepEqual(next.files.map((f) => f.id), ["existing", "f1"]);
  assert.deepEqual(next.ui.fileOrder, ["existing", "f1"], "moved files join the order");
});

test("the source loses exactly what moved, and its annotations with it", () => {
  const source = workspace({
    files: [file("f1", "a"), file("stays")],
    folders: [folder("a"), folder("keep")],
    saved: [
      { id: "s1", fileId: "f1", kind: "file", title: "x", createdAt: 0 },
      { id: "s2", fileId: "stays", kind: "file", title: "y", createdAt: 0 },
    ],
    highlights: [{ id: "h1", fileId: "f1", text: "t", color: "yellow" }],
  });
  const plan = planTransfer(source, workspace(), { fileIds: [], folderIds: ["a"] });
  const left = removeFromSource(source, plan);
  assert.deepEqual(left.files.map((f) => f.id), ["stays"]);
  assert.deepEqual(left.folders!.map((f) => f.id), ["keep"]);
  assert.deepEqual(left.saved!.map((s) => s.id), ["s2"], "the stayed file keeps its star");
  assert.equal(left.highlights!.length, 0);
});

test("an empty selection moves nothing", () => {
  const source = workspace({ files: [file("f1")] });
  const plan = planTransfer(source, workspace(), { fileIds: [], folderIds: [] });
  assert.deepEqual(transferCounts(plan), { files: 0, folders: 0, saved: 0, highlights: 0 });
  assert.deepEqual(removeFromSource(source, plan).files.map((f) => f.id), ["f1"]);
});

test("a file selected directly and via its folder is moved once", () => {
  const source = workspace({ files: [file("f1", "a")], folders: [folder("a")] });
  const plan = planTransfer(source, workspace(), { fileIds: ["f1"], folderIds: ["a"] });
  assert.equal(plan.files.length, 1);
});

// --- panes ---
//
// A moved document must stop being open here. A pane left holding a tab whose
// file no longer exists in this workspace paints an empty column the reader has
// no obvious way to close.

test("a moved document closes in every pane holding it", () => {
  const layout: PaneLayout = {
    panes: [
      { id: "p1", tabs: ["a", "gone"], activeTabId: "gone" },
      { id: "p2", tabs: ["gone", "b"], activeTabId: "b" },
    ],
    focusedPaneId: "p1",
  };
  const next = closeFileEverywhere(layout, ["gone"]);
  assert.ok(next.panes.every((pane) => !pane.tabs.includes("gone")));
  assert.equal(next.panes[0].activeTabId, "a", "the pane falls back to a surviving tab");
});

test("a pane emptied by the move collapses, and focus survives", () => {
  const layout: PaneLayout = {
    panes: [
      { id: "p1", tabs: ["stays"], activeTabId: "stays" },
      { id: "p2", tabs: ["gone"], activeTabId: "gone" },
    ],
    focusedPaneId: "p2",
  };
  const next = closeFileEverywhere(layout, ["gone"]);
  assert.equal(next.panes.length, 1);
  assert.equal(next.focusedPaneId, "p1", "focus cannot point at a pane that is gone");
});

test("moving everything leaves one empty pane rather than none", () => {
  const layout: PaneLayout = {
    panes: [{ id: "p1", tabs: ["a", "b"], activeTabId: "a" }],
    focusedPaneId: "p1",
  };
  const next = closeFileEverywhere(layout, ["a", "b"]);
  assert.equal(next.panes.length, 1);
  assert.equal(next.panes[0].activeTabId, null);
});

test("closing nothing returns the layout untouched", () => {
  const layout: PaneLayout = {
    panes: [{ id: "p1", tabs: ["a"], activeTabId: "a" }],
    focusedPaneId: "p1",
  };
  assert.equal(closeFileEverywhere(layout, []), layout);
});

test("counts describe what the reader is about to move", () => {
  const source = workspace({
    files: [file("f1", "a"), file("f2", "a")],
    folders: [folder("a"), folder("b", "a")],
    saved: [{ id: "s1", fileId: "f1", kind: "file", title: "x", createdAt: 0 }],
  });
  const plan = planTransfer(source, workspace(), { fileIds: [], folderIds: ["a"] });
  assert.deepEqual(transferCounts(plan), { files: 2, folders: 2, saved: 1, highlights: 0 });
});
